export const pyExercisesCh6to10 = {
        21: [
            { type: 'algostep', prompt: 'Selection sort begins on [64,25,12,22,11]', array: [64, 25, 12, 22, 11], step: 1, description: 'Pass 1 scans the whole array for the smallest value.', question: 'What does pass 1 do?', options: ['11→index 0', '12→index 0', '22→index 1', '25→index 0'], correct: 0, explanation: 'Selection sort scans for the minimum of the unsorted part and swaps it to the front — pass 1 finds 11 and puts it at index 0. Each pass fixes exactly one position for good, which is why it always takes n-1 passes no matter how sorted the input already is.', hint: 'Scan the whole array once. What is the smallest value, and where does this algorithm put it?' },
            { type: 'trace', prompt: 'After ONE bubble pass, what is guaranteed?', code: [{ text: '# Compare adjacent, swap if needed' }, { text: '[5,1]→swap [1,5,4,2,8]' }, { text: '[5,4]→swap [1,4,5,2,8]' }, { text: '[5,2]→swap [1,4,2,5,8]' }, { text: '[5,8]→ok   [1,4,2,5,8]', highlight: true }], options: ['Largest at end', 'Array sorted', 'Smallest at start', 'Nothing guaranteed'], correct: 0, explanation: 'Watch what travels: the 5 gets carried rightward by every swap until something bigger stops it — so after one pass the largest element has bubbled all the way to the end, and only that much is promised. The rest is still scrambled ([1,4,2,5,8] is not sorted). That one-guarantee-per-pass is why bubble sort needs up to n-1 passes.', hint: 'Follow the 5 through the swaps. Where does the biggest value always end up, and what happens to everything else?' },
            { type: 'realworld', prompt: 'The array is already 95% sorted. Which sort exploits that?', scenario: '📊 Two elements misplaced, the rest in order.', options: [{ code: 'insertion_sort(arr)', label: 'Insertion sort' }, { code: 'merge_sort(arr)', label: 'Merge sort' }, { code: 'quick_sort(arr)', label: 'Quick sort' }, { code: 'selection_sort(arr)', label: 'Selection sort' }], correct: 0, explanation: 'Insertion sort does almost no work on sorted input: each element compares once against its neighbour and stays put, so a nearly-sorted array finishes in about O(n). Merge sort does its full O(n log n) regardless — it never notices the input is easy. Selection sort scans the whole remainder every pass no matter what. And quicksort with a naive pivot is at its WORST on sorted data. This adaptivity is exactly why Timsort (Python\'s sorted) is built on insertion sort for small runs.', hint: 'Which algorithm gets to stop early when nothing needs moving? Walk one element of sorted input through each.' },
            { type: 'pair', prompt: 'Match each sort to its cost', pairs: [{ id: 1, left: 'Bubble, worst case', right: 'O(n²)' }, { id: 2, left: 'Merge, always', right: 'O(n log n)' }, { id: 3, left: 'Insertion, best case', right: 'O(n)' }, { id: 4, left: 'Python sorted()', right: 'Timsort' }], explanation: 'The qualifier matters as much as the number: merge sort is O(n log n) in EVERY case, insertion sort ranges from O(n) on sorted input to O(n²) on reversed input. Timsort — what sorted() and .sort() actually run — merges the two ideas: insertion sort on small runs, merge sort to combine them, so it inherits the O(n) best case AND the O(n log n) guarantee.' },
            { type: 'scramble', prompt: 'Assemble insertion sort', pieces: [{ id: 'a', text: 'def insertion_sort(arr):' }, { id: 'b', text: '    for i in range(1, len(arr)):' }, { id: 'c', text: '        key = arr[i]' }, { id: 'd', text: '        j = i - 1' }, { id: 'e', text: '        while j >= 0 and arr[j] > key:' }, { id: 'f', text: '            arr[j+1] = arr[j]; j -= 1' }, { id: 'g', text: '        arr[j+1] = key' }], distractors: [{ id: 'h', text: '        arr[j] = key' }], correctOrder: ['a', 'b', 'c', 'd', 'e', 'f', 'g'], explanation: 'key has to be saved BEFORE the shifting starts, because the shift overwrites arr[i]. The while walks left moving bigger elements one slot right, and when it stops, j+1 is the hole where key belongs. The spare line writes to arr[j] instead of arr[j+1] — off by one slot, which quietly overwrites an element instead of filling the hole.', hint: 'When the while loop stops, where exactly is the empty slot — at j, or at j+1?' },
            { type: 'output', prompt: 'What does this print?', code: [{ text: 'people = [("Bob", 25), ("Amy", 30), ("Cal", 25)]' }, { text: 'people.sort(key=lambda p: p[1])' }, { text: 'print([p[0] for p in people])' }], terminalOutput: "['Bob', 'Cal', 'Amy']", options: ["['Bob', 'Cal', 'Amy']", "['Amy', 'Bob', 'Cal']", "['Cal', 'Bob', 'Amy']", "['Bob', 'Amy', 'Cal']"], correct: 0, explanation: 'Python\'s sort is STABLE: records that tie on the key keep the order they already had, so Bob stays ahead of Cal at 25. That guarantee is what lets you sort by one field, then another, and get a proper multi-key ordering. An unstable sort could legally return Cal first, and quicksort implementations often do.', hint: 'Two people share age 25. What decides which of them comes first?' },
            { type: 'bug', prompt: 'This bubble sort never finishes. Which line is wrong?', code: [{ text: 'def bubble(a):', hasError: false }, { text: '    swapped = True', hasError: false }, { text: '    while swapped:', hasError: false }, { text: '        for i in range(len(a) - 1):', hasError: false }, { text: '            if a[i] > a[i+1]:', hasError: false }, { text: '                a[i], a[i+1] = a[i+1], a[i]', hasError: true }], correctLine: 5, explanation: 'The swap itself is correct — what is missing is swapped = False at the top of each pass and swapped = True right here. As written swapped never changes, so the while loop runs forever even on an already sorted list. The flag is the whole point of this variant: it lets a sorted input finish in one pass instead of n.', hint: 'What is meant to set swapped back to False, and what should turn it True again?' },
            { type: 'complexity', prompt: 'Sorting 1,000,000 numbers — which approach?', optionA: { code: 'for i in range(len(a)):\n    for j in range(len(a) - 1):\n        if a[j] > a[j+1]:\n            a[j], a[j+1] = a[j+1], a[j]', label: 'Bubble sort' }, optionB: { code: 'a.sort()', label: 'Built-in sort' }, correct: 'B', complexityA: 'O(n²)', complexityB: 'O(n log n)', explanation: 'A million squared is 10^12 comparisons — hours. n log n is about 2×10^7 — well under a second. Python\'s sort is Timsort, which also detects runs that are already ordered and handles nearly-sorted data in close to linear time. Hand-rolling a quadratic sort is almost never the right call.', hint: 'Square a million, then compare it to a million times twenty.' },
            { type: 'trace', prompt: 'After ONE full pass of selection sort, what is the list?', code: [{ text: 'a = [29, 10, 14, 37, 13]' }, { text: '# selection sort: find the minimum in a[i:],' }, { text: '# then swap it into position i' }, { text: '# ... one pass with i = 0 ...', highlight: true }], options: ['[10, 29, 14, 37, 13]', '[10, 13, 14, 29, 37]', '[13, 10, 14, 37, 29]', '[10, 14, 29, 37, 13]'], correct: 0, explanation: 'The smallest value in the whole list is 10 at index 1, so it swaps with whatever sits at index 0 — the 29 goes to index 1 and nothing else moves. Selection sort does exactly one swap per pass, which is its one genuine advantage: fewest writes of any simple sort, useful when writing is expensive. The second option is the fully sorted result, not one pass.', hint: 'Selection sort makes ONE swap per pass. Which two positions trade places?' },
            { type: 'pair', prompt: 'Match each sort to what makes it distinctive', pairs: [{ id: 1, left: 'Bubble sort', right: 'Swaps neighbours; stops early if a pass is clean' }, { id: 2, left: 'Selection sort', right: 'One swap per pass, fewest writes' }, { id: 3, left: 'Merge sort', right: 'O(n log n) guaranteed, needs extra space' }, { id: 4, left: 'Quicksort', right: 'Fast in practice, O(n²) on a bad pivot' }], explanation: 'The trade is always time against space against worst case. Merge sort never degrades but needs an O(n) buffer; quicksort sorts in place and is usually faster, yet a pathological pivot makes it quadratic — which is why real libraries randomise the pivot or switch algorithms partway. Python uses Timsort, a merge/insertion hybrid built for real-world nearly-sorted data.', hint: null },
        ],
        22: [
            { type: 'algostep', prompt: 'Binary search for 7 in [1,3,5,7,9,11,13]', array: [1, 3, 5, 7, 9, 11, 13], step: 1, description: 'lo=0, hi=6, so mid=3 — and arr[3] is checked first.', question: 'How many comparisons does finding 7 take?', options: ['1', '2', '3', '7'], correct: 0, explanation: 'The first midpoint of a 7-element array is index 3, and arr[3] happens to BE the 7 — one comparison, done. That is luck, not the general cost: the guarantee is at most log₂(n)+1 comparisons, so ⌈log₂(7)⌉ ≈ 3 in the worst case. 7 comparisons is what linear search would need if the target were last.', hint: 'Work out which index gets checked first. What value lives there?' },
            { type: 'trace', prompt: '6 is not in the array. What does the search do?', code: [{ text: 'def bsearch(arr, t):' }, { text: '    lo, hi = 0, len(arr)-1' }, { text: '    while lo <= hi:' }, { text: '        mid = (lo+hi)//2' }, { text: '        if arr[mid]==t: return mid' }, { text: '        elif arr[mid]<t: lo=mid+1' }, { text: '        else: hi=mid-1' }, { text: '    return -1', highlight: true }], options: ['Returns 2', 'Returns 3', 'Returns -1', 'Infinite loop'], correct: 2, explanation: 'Trace it: mid=2 → arr[2]=5 < 6 so lo=3; mid=3 → arr[3]=7 > 6 so hi=2. Now lo > hi, the while condition fails, and -1 comes back. The termination is no accident: every pass moves lo up or hi down, so the window must eventually close. An infinite loop is what you get if you write lo=mid instead of lo=mid+1.', hint: 'Run two iterations by hand. What are lo and hi after each, and when does the while stop?' },
            { type: 'errordecode', prompt: 'What is wrong with this midpoint line?', errorText: 'mid = (lo + hi) / 2  # TypeError when used as index:\narr[mid]  # list indices must be integers, not float', question: 'Safe midpoint?', options: ['lo + (hi-lo)//2', '(lo+hi) % 2', 'hi - lo', 'lo * hi'], correct: 0, explanation: 'In Python 3, / always produces a float, and a float cannot index a list — so the fix must use //. The lo + (hi-lo)//2 form is preferred over (lo+hi)//2 for a second reason that Python does not have but Java and C do: lo+hi can overflow a fixed-width int, and this famous bug sat in the JDK\'s own binary search for nine years. % 2 gives 0 or 1, and the other two are not midpoints at all.', hint: 'Two separate issues: what type does / return here, and what could lo+hi do in a fixed-width language?' },
            { type: 'realworld', prompt: 'What must be true of the array before binary search works?', scenario: '⚠️ Break the precondition and the search silently misses values that ARE there.', options: [{ code: 'arr = sorted(data)', label: 'It is sorted' }, { code: 'len(set(arr)) == len(arr)', label: 'All elements unique' }, { code: 'len(arr) < 1000', label: 'It is small' }, { code: 'isinstance(arr, list)', label: 'It is a list' }], correct: 0, explanation: 'Halving only works because comparing against the middle tells you WHICH half the target must be in — and that inference is only valid on sorted data. On unsorted data the search returns wrong answers silently, no error. Duplicates are fine (you just get one of the positions), size is irrelevant, and any indexable sequence works.', hint: 'The algorithm throws half the array away after one comparison. What justifies that?' },
            { type: 'fillgap', prompt: 'On a hit, keep searching left — find the FIRST occurrence', codeParts: [{ text: 'def first_occur(arr, t):\n    lo, hi, result = 0, len(arr)-1, -1\n    while lo <= hi:\n        mid = (lo+hi)//2\n        if arr[mid] == t:\n            ', type: 'fixed' }, { text: 'result = mid; hi = mid - 1', type: 'gap', id: 'g1' }, { text: '\n        elif arr[mid] < t: lo = mid+1\n        else: hi = mid-1\n    return result', type: 'fixed' }], bank: ['result = mid; hi = mid - 1', 'return mid', 'lo = mid + 1', 'break'], correctFill: { g1: 'result = mid; hi = mid - 1' }, explanation: 'A hit might not be the FIRST hit — there could be equal values further left. So the trick is to record the match and keep narrowing leftward; the last recorded mid is the leftmost occurrence. return mid and break both stop at whatever occurrence the search happened to land on, and lo = mid + 1 searches the wrong side, finding the LAST occurrence instead.', hint: 'On [5,7,7,7,9] searching 7, the first probe lands on the middle 7. What must happen next for the answer to be index 1?' },
            { type: 'bug', prompt: 'Binary search on [5, 2, 9, 1] returns the wrong answer. What is actually wrong?', code: [{ text: 'a = [5, 2, 9, 1]', hasError: true }, { text: 'lo, hi = 0, len(a) - 1', hasError: false }, { text: 'while lo <= hi:', hasError: false }, { text: '    mid = (lo + hi) // 2', hasError: false }, { text: '    if a[mid] == target: return mid', hasError: false }], correctLine: 0, explanation: 'The algorithm is fine; the INPUT breaks its precondition. Binary search only works on sorted data, because discarding half the range assumes everything left of mid is smaller. On unsorted input it happily returns a wrong answer with no error at all — the most dangerous kind of bug. Sort first, or use a linear scan.', hint: 'Every line of the search is textbook. What does binary search assume about the list it is given?' },
            { type: 'trace', prompt: 'Searching for 7 in [1,3,5,7,9,11] — how many comparisons?', code: [{ text: 'a = [1, 3, 5, 7, 9, 11]' }, { text: 'lo, hi = 0, 5' }, { text: '# mid = 2 → a[2] = 5, too small, lo = 3' }, { text: '# ... continue ...', highlight: true }], options: ['3', '1', '4', '6'], correct: 0, explanation: 'First mid is (0+5)//2 = 2 giving 5, too small so lo becomes 3. Next mid is (3+5)//2 = 4 giving 9, too big so hi becomes 3. Third mid is 3 giving 7 — found. Three comparisons for six items, and doubling the list only adds one more: that is what log2(n) buys you.', hint: 'Work out mid each round and write down what happens to lo and hi.' },
            { type: 'output', prompt: 'What does this print?', code: [{ text: 'import bisect' }, { text: 'a = [1, 3, 3, 3, 7]' }, { text: 'print(bisect.bisect_left(a, 3), bisect.bisect_right(a, 3))' }], terminalOutput: '1 4', options: ['1 4', '1 3', '0 4', '3 3'], correct: 0, explanation: 'bisect_left finds the FIRST position where 3 could go — index 1, in front of every existing 3 — and bisect_right finds the last, index 4. Subtracting them counts the duplicates: 4 - 1 = 3 threes. This is the standard trick for finding a range of equal keys, and both calls are O(log n).', hint: 'One lands before all the 3s, the other after. What is the gap between them?' },
            { type: 'refactor', prompt: 'Which mid calculation is safest?', originalCode: 'mid = (lo + hi) // 2', options: [{ code: 'mid = lo + (hi - lo) // 2', label: 'Offset from lo' }, { code: 'mid = (lo + hi) // 2', label: 'Sum then halve' }, { code: 'mid = hi // 2', label: 'Half of hi' }], correct: 0, explanation: 'Both of the first two are correct in Python, whose ints are unbounded — but the offset form is the habit worth having, because in Java, C or Rust lo + hi can overflow on a large array and produce a negative index. It is the famous bug that sat in the JDK binary search for nine years. The third ignores lo entirely and searches the wrong half once lo moves.', hint: 'One of these breaks in a fixed-width integer language. Which, and why does it not break here?' },
            { type: 'errordecode', prompt: 'The loop never ends. Decode the cause.', errorText: 'while lo < hi:\n    mid = (lo + hi) // 2\n    if a[mid] < target:\n        lo = mid          # <-- hangs here\n    else:\n        hi = mid', question: 'Why does this spin forever?', options: ['lo = mid does not shrink the range when mid == lo', 'The list is too large', 'mid is computed wrongly', 'It needs lo <= hi'], correct: 0, explanation: 'Once hi is lo + 1, mid rounds down to lo — so lo = mid assigns lo to itself and nothing moves. The range has to shrink every iteration: lo = mid + 1 in this branch. Every binary search bug is some version of this question — does each branch strictly reduce the interval?', hint: 'Put lo = 3 and hi = 4 in by hand. What is mid, and what does lo become?' },
        ],
        23: [
            { type: 'trace', prompt: 'How does the work grow when n doubles?', code: [{ text: 'for i in range(n):' }, { text: '    for j in range(n):' }, { text: '        print(i, j)' }], options: ['O(n)', 'O(n²)', 'O(n log n)', 'O(2ⁿ)'], correct: 1, explanation: 'The inner loop runs n times for each of the n outer passes — n × n = n². The practical meaning: double n and the work quadruples. O(n log n) would need the inner range to shrink or halve; O(2ⁿ) is a different universe, where adding ONE to n doubles the work.', hint: 'Count total prints for n=10, then for n=20. What is the ratio?' },
            { type: 'realworld', prompt: 'Binary search over a million sorted items — how many probes?', scenario: '🔍 1,000,000 sorted integers, one lookup.', options: [{ code: '~20', label: 'About twenty' }, { code: '~1,000,000', label: 'About a million' }, { code: '~500,000', label: 'About half a million' }, { code: '~1,000', label: 'About a thousand' }], correct: 0, explanation: 'Each probe halves the search space, and 2²⁰ ≈ 1,048,576 — so twenty halvings pin down one item among a million. That is the visceral meaning of O(log n): a thousand times more data costs only ten more probes. Half a million is the average for LINEAR search, and a thousand would be √n, which is no standard algorithm here.', hint: 'How many times can you halve 1,000,000 before reaching 1? Count powers of 2.' },
            { type: 'pair', prompt: 'Match each algorithm to its complexity', pairs: [{ id: 1, left: 'Binary Search', right: 'O(log n)' }, { id: 2, left: 'Bubble Sort', right: 'O(n²)' }, { id: 3, left: 'Merge Sort', right: 'O(n log n)' }, { id: 4, left: 'Hash Lookup', right: 'O(1) average' }], explanation: 'A useful reading: log n means "halves the problem each step", n² means "compares pairs", n log n means "divides, then touches everything per level", and O(1) average carries the word average for a reason — a pathological set of colliding keys degrades a hash table to O(n).' },
            { type: 'trace', prompt: 'i is halved each pass. What is the complexity?', code: [{ text: 'i = n' }, { text: 'while i > 0:' }, { text: '    print(i)' }, { text: '    i = i // 2', highlight: true }], options: ['O(n)', 'O(log n)', 'O(n²)', 'O(1)'], correct: 1, explanation: 'The loop variable is divided, not decremented — that single character difference is the whole answer. From n it takes log₂(n) halvings to reach 0, so the loop body runs O(log n) times. Change the line to i -= 2 and it becomes O(n). Spotting divide-versus-subtract in the update is the fastest complexity tell there is.', hint: 'Look only at the highlighted line. Is i shrinking by a constant amount, or by a constant factor?' },
            { type: 'refactor', prompt: 'The membership check runs thousands of times. Which rewrite pays off?', originalCode: '# Runs in a hot loop:\nif x in my_list:\n    ...', options: [{ code: 'lookup = set(my_list)   # once\nif x in lookup:\n    ...', label: 'Build a set, check the set' }, { code: 'my_list.sort()          # once\ni = bisect.bisect_left(my_list, x)\nif i < len(my_list) and my_list[i] == x:\n    ...', label: 'Sort once, bisect each time' }, { code: 'found = False\nfor item in my_list:\n    if item == x:\n        found = True\n        break', label: 'Loop with early exit' }], correct: 0, explanation: 'The set costs O(n) once, then every check is O(1) — thousands of checks amortise the build immediately. The bisect version genuinely works too, but each check is O(log n) and sorting may destroy an order you needed; it earns its place only when you also need range queries. The manual loop is exactly what `in` already does — same O(n), more code.', hint: 'Separate the one-time cost from the per-check cost. Which option has the cheapest per-check?' },
            { type: 'complexity', prompt: 'Which is faster for "is x in here?" on 100,000 items, called often?', optionA: { code: 'if x in my_list:\n    ...', label: 'Membership on a list' }, optionB: { code: 'if x in my_set:\n    ...', label: 'Membership on a set' }, correct: 'B', complexityA: 'O(n)', complexityB: 'O(1)', explanation: 'The syntax is identical, which is what makes this so easy to miss: `in` on a list scans element by element, while on a set (or a dict) it hashes and jumps straight to the bucket. Building the set costs O(n) once, so it pays off the moment you look up more than a couple of times. Same three characters, hundred-thousand-fold difference.', hint: 'The two lines look the same. What does each data structure have to do to answer?' },
            { type: 'output', prompt: 'How many times does the inner line run?', code: [{ text: 'count = 0' }, { text: 'for i in range(n):' }, { text: '    for j in range(i):' }, { text: '        count += 1' }, { text: '# n = 100' }], terminalOutput: '4950', options: ['4950', '10000', '100', '5000'], correct: 0, explanation: 'The inner loop runs 0, then 1, then 2 … up to n-1 times, so the total is n(n-1)/2 = 4950 — half of n² and change. Big-O still calls it O(n²) because constant factors are dropped, and that is the right call: at n = 1,000,000 the halving is irrelevant next to the squaring.', hint: 'The inner loop is not the same length each time. Add up 0 + 1 + 2 + … + 99.' },
            { type: 'pair', prompt: 'Match each operation to its complexity', pairs: [{ id: 1, left: 'list.append(x)', right: 'O(1) amortised' }, { id: 2, left: 'list.insert(0, x)', right: 'O(n) — everything shifts' }, { id: 3, left: 'dict[key]', right: 'O(1) average' }, { id: 4, left: 'sorted(list)', right: 'O(n log n)' }], explanation: 'append is amortised O(1): most calls are instant, and the occasional resize copies everything but happens rarely enough to average out. insert(0, x) has to move every existing element one place right, so a loop of them is quadratic — collections.deque exists precisely for that case, with O(1) at both ends.', hint: null },
            { type: 'refactor', prompt: 'Which version finds duplicates efficiently?', originalCode: 'dupes = []\nfor i in range(len(a)):\n    for j in range(i + 1, len(a)):\n        if a[i] == a[j]:\n            dupes.append(a[i])', options: [{ code: 'seen = set()\ndupes = [x for x in a if x in seen or seen.add(x)]', label: 'Set of seen values' }, { code: 'dupes = [x for x in a if a.count(x) > 1]', label: 'count per element' }, { code: 'dupes = list(set(a))', label: 'Set round-trip' }], correct: 0, explanation: 'One pass with a set is O(n): each membership test is constant time. The count version looks shorter but calls count once per element and count itself scans the list — still O(n²), just hidden inside a builtin, which is the more dangerous form of the same mistake. The third returns the UNIQUE values, answering a different question entirely.', hint: 'The second option has one visible loop. How many hidden ones does count add?' },
            { type: 'trace', prompt: 'What is the complexity of this function?', code: [{ text: 'def f(n):' }, { text: '    total = 0' }, { text: '    while n > 1:' }, { text: '        total += n' }, { text: '        n = n // 2', highlight: true }, { text: '    return total' }], options: ['O(log n)', 'O(n)', 'O(n log n)', 'O(1)'], correct: 0, explanation: 'n halves every pass, so it takes about log2(n) steps to reach 1 — 19 iterations for a million, 29 for a billion. Halving (or doubling) each round is the fingerprint of a logarithmic loop, and it is exactly why binary search and balanced trees scale so well.', hint: 'How many times can you halve a million before you reach 1?' },
        ],
        24: [
            { type: 'trace', prompt: 'Which pair does the brute force return first?', code: [{ text: 'def two_sum(nums, t):' }, { text: '    for i in range(len(nums)):' }, { text: '        for j in range(i+1, len(nums)):' }, { text: '            if nums[i]+nums[j]==t:' }, { text: '                return [i,j]' }, { text: 'print(two_sum([2,7,11,15], 9))', highlight: true }], options: ['[0, 1]', '[1, 2]', '[0, 3]', 'None'], correct: 0, explanation: 'The very first pair tried is i=0, j=1: nums[0]+nums[1] = 2+7 = 9 — immediate hit, and the function returns INDICES, not the values themselves. Note j starts at i+1, which is what prevents both using the same element twice and checking each pair twice. None only happens if every pair misses.', hint: 'What is the first (i, j) the loops generate, and what do those two values sum to?' },
            { type: 'refactor', prompt: 'Which rewrite makes two-sum a single pass AND keeps the indices right?', originalCode: 'for i in range(len(nums)):\n    for j in range(i+1, len(nums)):\n        if nums[i]+nums[j]==target: return [i,j]', options: [{ code: 'seen = {}\nfor i, n in enumerate(nums):\n    comp = target - n\n    if comp in seen: return [seen[comp], i]\n    seen[n] = i', label: 'Dict of value→index' }, { code: 'nums.sort()\nlo, hi = 0, len(nums)-1\n# then walk pointers inward', label: 'Sort, then two pointers' }, { code: 'for n in nums:\n    if target - n in nums:\n        return [nums.index(n), nums.index(target-n)]', label: 'Check complement with in' }], correct: 0, explanation: 'The dict answers "have I already seen my complement?" in O(1), one pass total. The two-pointer version is genuinely O(n log n) and elegant — but sort() destroys the original indices, which the problem asks for; you would need to sort (value, index) pairs. The `in` version looks linear but both `in nums` and .index are themselves O(n) scans, so it is still quadratic — and it also breaks when n is its own complement, returning the same index twice.', hint: 'Two of these are faster than the original. Which one still returns the ORIGINAL indices without extra bookkeeping?' },
            { type: 'scramble', prompt: 'Assemble the one-pass two-sum', pieces: [{ id: 'a', text: 'def two_sum(nums, target):' }, { id: 'b', text: '    seen = {}' }, { id: 'c', text: '    for i, n in enumerate(nums):' }, { id: 'd', text: '        comp = target - n' }, { id: 'e', text: '        if comp in seen:' }, { id: 'f', text: '            return [seen[comp], i]' }, { id: 'g', text: '        seen[n] = i' }], distractors: [{ id: 'h', text: '        seen[i] = n' }], correctOrder: ['a', 'b', 'c', 'd', 'e', 'f', 'g'], explanation: 'The check must come BEFORE the insert: check-then-add is what stops an element pairing with itself when target is 2n. The dict maps value→index, so seen[comp] retrieves where the complement was. The spare line maps index→value — backwards, so `comp in seen` would be asking whether the complement is an INDEX, silently wrong on most inputs.', hint: 'The dict is asked "where did I see this VALUE?". Which way round must the keys go for that question to work?' },
            { type: 'output', prompt: 'n iterations, each doing an O(1) lookup — total?', code: [{ text: '# The hash-map two_sum:' }, { text: '#   the loop body runs n times' }, { text: '#   each body does one dict lookup + one insert' }, { text: '# Total = iterations x cost per iteration = ?', highlight: true }], terminalOutput: 'O(n)', options: ['O(n²)', 'O(n)', 'O(n log n)', 'O(1)'], correct: 1, explanation: 'n iterations × O(1) each = O(n). The mistake this question exists to catch is multiplying the loop by the SIZE of the dict instead of the COST of the lookup — the dict grows to n entries, but each lookup stays O(1) regardless, because that is the entire point of hashing. O(1) total would mean the loop itself vanished.', hint: 'Multiply the number of iterations by the cost of one iteration — not by the size of anything.' },
            { type: 'output', prompt: 'What does this print?', code: [{ text: 'def mystery(a):' }, { text: '    for i in range(1, len(a)):' }, { text: '        key = a[i]' }, { text: '        j = i - 1' }, { text: '        while j >= 0 and a[j] > key:' }, { text: '            a[j+1] = a[j]' }, { text: '            j -= 1' }, { text: '        a[j+1] = key' }, { text: '    return a' }, { text: '' }, { text: 'print(mystery([4, 2, 7, 1]))' }], terminalOutput: '[1, 2, 4, 7]', options: ['[1, 2, 4, 7]', '[7, 4, 2, 1]', '[4, 2, 7, 1]', '[2, 4, 1, 7]'], correct: 0, explanation: 'This is insertion sort: take each element and slide it left past everything bigger. It is O(n²) in general but nearly linear on almost-sorted data, which is why real libraries switch to it for small or nearly-ordered chunks — Timsort and most quicksorts do exactly that below a threshold.', hint: 'Trace what happens to the 2 when i = 1. Where does it end up relative to the 4?' },
            { type: 'complexity', prompt: 'Counting word frequencies in a large document', optionA: { code: 'counts = {}\nfor w in words:\n    counts[w] = counts.get(w, 0) + 1', label: 'Dict accumulator' }, optionB: { code: 'counts = {}\nfor w in set(words):\n    counts[w] = words.count(w)', label: 'count per unique word' }, correct: 'A', complexityA: 'O(n)', complexityB: 'O(n·u)', explanation: 'The dict version touches each word once. The second looks tidier but calls count for every unique word, and each count rescans the whole list — with 10,000 unique words in a million-word document that is 10^10 operations. A builtin doing the scanning does not make the scanning free; that is the trap.', hint: 'How many times does the second version walk the full word list?' },
            { type: 'errordecode', prompt: 'Decode this error', errorText: 'Traceback (most recent call last):\n  File "main.py", line 4, in <module>\n    for i in range(len(a)):\n        a.remove(a[i])\nIndexError: list index out of range', question: 'What causes this?', options: ['The list shrinks while the loop range was fixed at the start', 'remove needs an index, not a value', 'range cannot take len()', 'The list was empty'], correct: 0, explanation: 'range(len(a)) is evaluated ONCE, before the first iteration, so it still counts the original length while remove shortens the list underneath it — eventually i points past the end. Mutating a sequence you are iterating is a bug in every language. Build a new list with a comprehension, or iterate over a copy with a[:].', hint: 'When is the range computed, and what is happening to the list after that?' },
            { type: 'refactor', prompt: 'Which finds the two largest values best?', originalCode: 'a.sort()\ntop2 = a[-2:]', options: [{ code: 'import heapq\ntop2 = heapq.nlargest(2, a)', label: 'heapq.nlargest' }, { code: 'top2 = sorted(a)[-2:]', label: 'sorted then slice' }, { code: 'top2 = [max(a), max(x for x in a if x != max(a))]', label: 'max twice' }], correct: 0, explanation: 'nlargest keeps a heap of just k items, so it is O(n log k) — effectively linear when k is 2 — and it leaves the input untouched. Sorting is O(n log n) for information you mostly throw away, and the original also MUTATES the caller\'s list. The third recomputes max inside a generator, so it is quadratic, and it silently drops a legitimate duplicate maximum.', hint: 'You need 2 values out of n. Does that justify ordering all n?' },
            { type: 'fillgap', prompt: 'Complete: is this list already sorted?', codeParts: [{ text: 'def is_sorted(a):\n    return ', type: 'fixed' }, { text: 'all(a[i] <= a[i+1] for i in range(len(a) - 1))', type: 'gap', id: 'g1' }, { text: '\n\nprint(is_sorted([1, 2, 2, 5]))  # True', type: 'fixed' }], bank: ['all(a[i] <= a[i+1] for i in range(len(a) - 1))', 'all(a[i] < a[i+1] for i in range(len(a) - 1))', 'a == a.sort()', 'all(a[i] <= a[i+1] for i in range(len(a)))'], correctFill: { g1: 'all(a[i] <= a[i+1] for i in range(len(a) - 1))' }, explanation: 'Compare each neighbouring pair and stop at the first that is out of order — all short-circuits, so a badly sorted list is rejected immediately. The strict < wrongly calls [1,2,2,5] unsorted. a.sort() returns None and sorts in place, so that comparison is always False. And the last option runs i to len-1, so a[i+1] walks off the end.', hint: 'The list contains two equal neighbours. Which comparison accepts that, and which range stays in bounds?' },
            { type: 'realworld', prompt: 'Which one checks if two words are anagrams?', scenario: '🔤 "listen" and "silent" — same letters, rearranged?', options: [{ code: 'sorted(a) == sorted(b)', label: 'Compare sorted letters' }, { code: 'len(a) == len(b)', label: 'Compare lengths' }, { code: 'set(a) == set(b)', label: 'Compare letter sets' }, { code: 'a in b or b in a', label: 'Substring test' }], correct: 0, explanation: 'Sorting both puts identical multisets into identical order, so the comparison is exact — O(n log n), or O(n) with Counter(a) == Counter(b). Length alone passes for any two words of the same size. Sets lose the COUNTS, so "aab" and "abb" wrongly match. And neither word is a substring of the other here.', hint: 'Two of these ignore how many times each letter appears. Which one does not?' },
        ],
        // ═══ CH7: DATA STRUCTURES II ⭐⭐⭐ ═══
        25: [
            { type: 'trace', prompt: 'Push 1, 2, 3, then pop twice. What remains?', code: [{ text: 'stack = []' }, { text: 'stack.append(1); stack.append(2); stack.append(3)' }, { text: 'stack.pop(); stack.pop()' }, { text: 'print(stack)', highlight: true }], options: ['[1]', '[3]', '[1,2]', '[]'], correct: 0, explanation: 'pop() removes from the END — last in, first out. The two pops take 3 then 2, leaving [1]. Answering [3] means thinking of a queue, where the earliest items leave first; that is exactly the distinction this question tests. In Python a plain list IS the stack idiom: append and pop both work at the tail in O(1).', hint: 'Which end does pop() take from? Remove twice from that end.' },
            { type: 'realworld', prompt: 'Which structure checks "({[]})" correctly?', scenario: '🔍 "({[]})" is balanced; "([)]" is not — same counts, wrong ORDER.', options: [{ code: 'stack: push opener, on closer pop and compare', label: 'Stack' }, { code: 'queue: enqueue opener, on closer dequeue and compare', label: 'Queue' }, { code: 'count = openers - closers; balanced if 0', label: 'Counter' }, { code: 'balanced if set(openers) == set(matching closers)', label: 'Set' }], correct: 0, explanation: 'The most recently opened bracket must close first — that is literally LIFO, so a stack mirrors the structure. The counter is the instructive failure: "([)]" has matching counts and still is not balanced, because nesting is about order, not quantity. A queue checks the OLDEST opener first, backwards. Sets ignore both order and count.', hint: 'Test each candidate on "([)]" — counts match, order does not. Which structure notices?' },
            { type: 'pair', prompt: 'Match each structure to its discipline', pairs: [{ id: 1, left: 'Stack', right: 'Last in, first out' }, { id: 2, left: 'Queue', right: 'First in, first out' }, { id: 3, left: 'Deque', right: 'Both ends open' }, { id: 4, left: 'Priority Queue', right: 'Best out first' }], explanation: 'The discipline — who leaves first — is the entire difference; the storage underneath can be identical. A priority queue is the odd one out: departure order depends on a comparison, not on arrival time, which is why it is backed by a heap rather than a list. Python note: use collections.deque for queues, because list.pop(0) shifts every element.' },
            { type: 'scramble', prompt: 'Assemble the balanced-brackets checker', pieces: [{ id: 'a', text: 'def is_valid(s):' }, { id: 'b', text: '    stack = []' }, { id: 'c', text: '    pairs = {")":"(", "]":"[", "}":"{"}' }, { id: 'd', text: '    for c in s:' }, { id: 'e', text: '        if c in "([{": stack.append(c)' }, { id: 'f', text: '        elif not stack or stack.pop() != pairs[c]:' }, { id: 'g', text: '            return False' }, { id: 'h', text: '    return len(stack) == 0' }], distractors: [{ id: 'i', text: '    return True' }], correctOrder: ['a', 'b', 'c', 'd', 'e', 'f', 'g', 'h'], explanation: 'Two subtleties carry the algorithm. `not stack` must be checked before popping — a closer with nothing open (")(" ) would otherwise crash. And the final line must verify the stack is EMPTY: plain return True passes "(((", where openers never closed. The three ways to fail are wrong pair, early closer, unclosed opener — one line each.', hint: 'Three ways to be unbalanced: wrong match, closer-first, opener never closed. Find the line that catches each.' },
            { type: 'trace', prompt: 'Enqueue A, B, C — which two leave first?', code: [{ text: 'from collections import deque' }, { text: 'q = deque()' }, { text: 'q.append("A"); q.append("B"); q.append("C")' }, { text: 'print(q.popleft(), q.popleft())', highlight: true }], options: ['A B', 'C B', 'A C', 'B C'], correct: 0, explanation: 'popleft takes from the FRONT, so departures follow arrivals: A then B. "C B" is stack thinking. deque exists precisely because list.pop(0) must shift every remaining element — O(n) per dequeue — while popleft is O(1) at both ends.', hint: 'append adds at the right, popleft removes at the left. Who has been waiting longest?' },
            { type: 'output', prompt: 'What does this print?', code: [{ text: 'from collections import deque' }, { text: 'q = deque([1, 2, 3])' }, { text: 'q.append(4)' }, { text: 'print(q.popleft(), q.pop())' }], terminalOutput: '1 4', options: ['1 4', '4 1', '1 3', '3 1'], correct: 0, explanation: 'popleft takes from the FRONT — 1, the oldest — and pop takes from the back, which is the 4 just appended. A deque supports both ends in O(1), so it can behave as a queue or a stack. A plain list can too, but list.pop(0) shifts every remaining element and turns a queue loop quadratic.', hint: 'One of these takes from the front and one from the back. Which end did the 4 join?' },
            { type: 'bug', prompt: 'This queue gets slower as it grows. Which line is the problem?', code: [{ text: 'queue = []', hasError: false }, { text: 'queue.append(job)', hasError: false }, { text: 'nxt = queue.pop(0)', hasError: true }, { text: 'process(nxt)', hasError: false }], correctLine: 2, explanation: 'pop(0) removes the first element and then shifts every remaining one left — O(n) per call, so draining a queue of n jobs costs O(n²). collections.deque with popleft() is O(1) and the rest of the code is unchanged. Nothing errors here; it just quietly stops scaling, which is why it survives code review so often.', hint: 'Which line has to touch every other element to do its job?' },
            { type: 'errordecode', prompt: 'Decode this error', errorText: 'Traceback (most recent call last):\n  File "main.py", line 5, in <module>\n    top = stack.pop()\nIndexError: pop from empty list', question: 'What is missing?', options: ['A check that the stack is not empty before popping', 'A larger stack', 'A type annotation', 'A return statement'], correct: 0, explanation: 'Popping an empty stack has no answer to give, so Python raises rather than inventing one. Guard with `if stack:` before popping, or catch IndexError. This is the classic bracket-matcher bug: a closing bracket arrives with nothing open, and the check for it is the same check that detects the unbalanced input.', hint: 'What is in the stack at the moment line 5 runs?' },
            { type: 'fillgap', prompt: 'Complete: check whether brackets are balanced', codeParts: [{ text: 'stack = []\nfor ch in s:\n    if ch == "(": stack.append(ch)\n    elif ch == ")":\n        ', type: 'fixed' }, { text: 'if not stack: return False', type: 'gap', id: 'g1' }, { text: '\n        stack.pop()\nreturn not stack', type: 'fixed' }], bank: ['if not stack: return False', 'if stack: return False', 'if not stack: return True', 'if len(stack) == 0: continue'], correctFill: { g1: 'if not stack: return False' }, explanation: 'A closing bracket with nothing on the stack means it never had a partner — unbalanced, so return False. The final `return not stack` catches the opposite failure, an opening bracket left unmatched. Together they cover both directions; the other options either reject valid input, accept invalid input, or skip the pop and lose count.', hint: 'A ) has arrived and the stack is empty. Is that string balanced?' },
            { type: 'realworld', prompt: 'Which structure fits undo in a text editor?', scenario: '↩️ Ctrl+Z should undo the most recent action first.', options: [{ code: 'history = []\nhistory.append(action)\nlast = history.pop()', label: 'Stack: append and pop' }, { code: 'from collections import deque\nhistory = deque()\nhistory.append(action)\nfirst = history.popleft()', label: 'Queue: append and popleft' }, { code: 'history = set()\nhistory.add(action)', label: 'Set of actions' }, { code: 'history = {}\nhistory[action] = True', label: 'Dict keyed by action' }], correct: 0, explanation: 'Undo is last-in-first-out by definition, which is exactly a stack. A queue would undo your OLDEST action first — the opposite of what Ctrl+Z means. A set discards duplicates, so doing the same action twice would only be undoable once, and it keeps no order at all; the dict has the same problem.', hint: 'Which action does Ctrl+Z undo — the first one you did or the last?' },
        ],
        26: [
            { type: 'trace', prompt: 'What is a.next.val in this chain?', code: [{ text: 'class Node:' }, { text: '    def __init__(self, val): self.val=val; self.next=None' }, { text: 'a=Node(1); b=Node(2); c=Node(3)' }, { text: 'a.next=b; b.next=c' }, { text: 'print(a.next.val)', highlight: true }], options: ['1', '2', '3', 'None'], correct: 1, explanation: 'a.next points at b, and b.val is 2. Reading a chain of dots left to right — a, then .next (b), then .val — is the core skill for every linked-structure problem. a.next.next.val would be 3, and c.next is None, which is how the end of a list announces itself.', hint: 'Resolve one dot at a time: what object is a.next? Then take its val.' },
            { type: 'scramble', prompt: 'Assemble the list traversal', pieces: [{ id: 'a', text: 'def traverse(head):' }, { id: 'b', text: '    curr = head' }, { id: 'c', text: '    while curr:' }, { id: 'd', text: '        print(curr.val)' }, { id: 'e', text: '        curr = curr.next' }], distractors: [{ id: 'f', text: '        curr = curr.prev' }], correctOrder: ['a', 'b', 'c', 'd', 'e'], explanation: 'The loop condition is `while curr`, not `while curr.next` — the latter stops one node early and never prints the last value, the most common traversal off-by-one. Advancing via a separate curr keeps head intact for whoever still needs the list. The spare line needs .prev, which singly-linked nodes do not have.', hint: 'When should the loop stop: at the last node, or after it? Check which condition prints the final value.' },
            { type: 'realworld', prompt: 'Where does a linked list actually beat an array?', scenario: '🤔 Same data, different dominant operation.', options: [{ code: 'insert/remove at the FRONT, constantly', label: 'Heavy work at the head' }, { code: 'data[i] for random i, constantly', label: 'Random access by index' }, { code: 'sort the data repeatedly', label: 'Frequent sorting' }, { code: 'binary search over sorted data', label: 'Binary search' }], correct: 0, explanation: 'Inserting at a list head is relinking two pointers — O(1) — where an array must shift everything. Everything else favours the array: indexing a linked list walks i nodes, sorting wants cheap swaps and locality, and binary search NEEDS O(1) indexing to jump to mid, so it degrades to useless on a linked list. One honest niche, not a general upgrade.', hint: 'Three of these need to jump to arbitrary positions. Which one only ever touches the front?' },
            { type: 'trace', prompt: 'What does this pointer dance accomplish?', code: [{ text: 'prev = None; curr = head' }, { text: 'while curr:' }, { text: '    nxt = curr.next' }, { text: '    curr.next = prev' }, { text: '    prev = curr' }, { text: '    curr = nxt' }, { text: '# when the loop ends, what is prev?', highlight: true }], options: ['The reversed list\'s head, in O(n)', 'The unchanged head', 'None — the list was lost', 'The reversed head, in O(n²)'], correct: 0, explanation: 'Each pass flips one arrow: nxt saves the rest of the list BEFORE curr.next is overwritten — skip that save and the list really is lost, which is the third option. One walk, constant work per node, so O(n) with O(1) extra space. When curr runs off the end, prev holds the last node: the new head.', hint: 'Why is nxt saved first? Delete that line mentally and see what curr = nxt would do.' },
            { type: 'output', prompt: 'What does this print?', code: [{ text: 'class Node:' }, { text: '    def __init__(self, v): self.v = v; self.next = None' }, { text: '' }, { text: 'a = Node(1); b = Node(2)' }, { text: 'a.next = b' }, { text: 'print(a.next.v, b.next)' }], terminalOutput: '2 None', options: ['2 None', '2 2', '1 None', 'None None'], correct: 0, explanation: 'a.next points at b, so a.next.v is 2 — and b.next was never assigned, so it is still None, which is how the list marks its end. Every traversal is a loop that walks .next until it hits that None. Forgetting to check for it is the fastest route to AttributeError: NoneType has no attribute.', hint: 'Only one link was created. What is on the other side of b?' },
            { type: 'bug', prompt: 'This traversal crashes on the last node. Which line is wrong?', code: [{ text: 'cur = head', hasError: false }, { text: 'while cur.next is not None:', hasError: true }, { text: '    print(cur.v)', hasError: false }, { text: '    cur = cur.next', hasError: false }], correctLine: 1, explanation: 'The condition stops one node early: when cur is the LAST node its .next is None, so the loop exits before printing it. The correct test is `while cur is not None` (or just `while cur`), which visits every node and stops when the walk falls off the end. Off-by-one in a linked list is a condition problem, not an index problem.', hint: 'Which node does the loop refuse to print, and what is its .next?' },
            { type: 'trace', prompt: 'What does the list look like after these lines?', code: [{ text: '# list is 1 -> 2 -> 3' }, { text: 'prev, cur = None, head' }, { text: 'nxt = cur.next' }, { text: 'cur.next = prev' }, { text: 'prev, cur = cur, nxt', highlight: true }], options: ['1 points at None; cur is now node 2', '1 points at 2; cur is now node 3', 'The list is fully reversed', 'The list is unchanged'], correct: 0, explanation: 'This is one iteration of the standard reversal. Saving nxt first is what makes it safe — cur.next is about to be overwritten, and without the copy the rest of the list would be unreachable. After this pass node 1 terminates the new list and the walk has moved to node 2. Repeating it n times reverses everything in O(n) with no extra memory.', hint: 'Read the four assignments in order. What is node 1 pointing at when they finish?' },
            { type: 'complexity', prompt: 'Inserting at the FRONT, one million times', optionA: { code: 'lst.insert(0, x)', label: 'Python list' }, optionB: { code: 'node = Node(x)\nnode.next = head\nhead = node', label: 'Linked list' }, correct: 'B', complexityA: 'O(n) per insert', complexityB: 'O(1) per insert', explanation: 'A list stores elements contiguously, so inserting at index 0 shifts every existing one — a million of those is 10^12 moves. A linked list just points the new node at the old head, which is constant time regardless of length. The trade is the other direction: reaching element 500,000 is instant in a list and a 500,000-step walk in a linked list.', hint: 'What does each structure have to move to make room at the front?' },
            { type: 'realworld', prompt: 'Which detects a cycle in a linked list?', scenario: '🔁 Some node points back to an earlier one, so a walk never ends.', options: [{ code: 'slow = fast = head\nwhile fast and fast.next:\n    slow = slow.next\n    fast = fast.next.next\n    if slow is fast: return True', label: 'Two pointers at different speeds' }, { code: 'cur = head\nwhile cur:\n    cur = cur.next\nreturn False', label: 'Walk to the end' }, { code: 'return len(lst) > 0', label: 'Check the length' }, { code: 'return head.next is head', label: 'Compare head to its next' }], correct: 0, explanation: 'Floyd cycle detection: the fast pointer gains one node per step, so inside a loop it must eventually land on the slow one — O(n) time and O(1) space. Walking to the end never terminates on a cyclic list, which is the very bug being looked for. The last option only catches a node pointing at itself, missing every larger cycle.', hint: 'Two runners on a circular track at different speeds. What eventually happens?' },
            { type: 'pair', prompt: 'Match each operation to its cost on a singly linked list', pairs: [{ id: 1, left: 'Insert at head', right: 'O(1) — repoint two references' }, { id: 2, left: 'Access the 500th element', right: 'O(n) — walk from the head' }, { id: 3, left: 'Delete a node you already hold', right: 'O(1) if you also hold the one before it' }, { id: 4, left: 'Find a value', right: 'O(n) — no way to skip ahead' }], explanation: 'Everything a linked list is good at comes from having no contiguous block to shift, and everything it is bad at comes from having no index arithmetic. That is why deleting needs the PREVIOUS node — with only the target in hand you cannot repair the link pointing into it, which is exactly what doubly linked lists carry an extra pointer to fix.', hint: null },
        ],
        27: [
            { type: 'trace', prompt: 'In-order traversal of this BST prints what?', code: [{ text: '#       4' }, { text: '#      / \\' }, { text: '#     2   6' }, { text: '#    / \\' }, { text: '#   1   3' }, { text: '# in-order: visit left subtree, node, right subtree', highlight: true }], options: ['4 2 1 3 6', '1 2 3 4 6', '1 3 2 6 4', '4 2 6 1 3'], correct: 1, explanation: 'In-order goes fully left first: 1, back to 2, then 3, up to 4, then 6 — ascending order. That is not luck: BST invariant (left < node < right) plus in-order = sorted output, always. The first option is pre-order, the third post-order, the last level-order; recognising all four from output is worth drilling.', hint: 'Fully left before every node, right after. Start at the deepest left leaf.' },
            { type: 'pair', prompt: 'Match each traversal to its visiting order', pairs: [{ id: 1, left: 'In-order', right: 'Left, root, right' }, { id: 2, left: 'Pre-order', right: 'Root, left, right' }, { id: 3, left: 'Post-order', right: 'Left, right, root' }, { id: 4, left: 'Level-order', right: 'Layer by layer (BFS)' }], explanation: 'The name says where the ROOT goes: pre (first), in (middle), post (last). Each has a job — pre-order copies a tree, post-order deletes one safely (children before parent), and level-order is the odd one out: it needs a queue, not recursion, because it crosses branches.' },
            { type: 'realworld', prompt: 'What falls out of in-order on a Binary SEARCH Tree?', scenario: '🌳 Not just any binary tree — one with the BST ordering invariant.', options: [{ code: 'the values, in ascending order, O(n)', label: 'Sorted output' }, { code: 'the values, largest first', label: 'Reverse sorted' }, { code: 'insertion order', label: 'Insertion order' }, { code: 'root first, then by depth', label: 'By depth' }], correct: 0, explanation: 'The invariant (left < node < right) applied recursively means "everything printed before a node is smaller" — so in-order streams the whole tree in ascending order in one O(n) pass. Reverse sorted is one edit away: traverse right first. Insertion order is gone forever; the tree reorganised it. This property is why databases love B-trees for range queries.', hint: 'Combine two facts: what in-order visits first, and what the BST promises lives on the left.' },
            { type: 'trace', prompt: 'Searching this BST for 3 — how many nodes are visited?', code: [{ text: '#       4        3 < 4 → go left' }, { text: '#      / \\' }, { text: '#     2   6      3 > 2 → go right' }, { text: '#    / \\' }, { text: '#   1   3        found', highlight: true }], options: ['3', '2', '4', '5'], correct: 0, explanation: 'The path is 4 → 2 → 3: three nodes, one comparison each. That path length is the depth of the target, and in a balanced tree depth is about log₂(n) — the entire reason BSTs exist. Skew the same values into a chain (1→2→3→4→6) and the same search visits nearly every node: O(log n) is a promise about SHAPE, not about trees in general.', hint: 'Count every node the search touches, including the one where it stops.' },
            { type: 'output', prompt: 'In-order traversal of this tree prints what?', code: [{ text: '#       4' }, { text: '#      / \\' }, { text: '#     2   6' }, { text: '#    / \\' }, { text: '#   1   3' }, { text: '' }, { text: 'def inorder(n):' }, { text: '    if not n: return' }, { text: '    inorder(n.left); print(n.v, end=" "); inorder(n.right)' }], terminalOutput: '1 2 3 4 6', options: ['1 2 3 4 6', '4 2 1 3 6', '1 3 2 6 4', '4 2 6 1 3'], correct: 0, explanation: 'In-order visits left, then the node, then right — and on a binary SEARCH tree that always comes out sorted, which is the single most useful property of the shape. The second option is pre-order (node first), the third post-order (node last), the fourth level-order. Where the print sits among the two recursive calls is the entire difference.', hint: 'The print sits between the two recursive calls. What does that ordering give you on a search tree?' },
            { type: 'trace', prompt: 'Searching for 3 — how many nodes are visited?', code: [{ text: '#       8' }, { text: '#      / \\' }, { text: '#     3   10' }, { text: '#    / \\' }, { text: '#   1   6' }, { text: '' }, { text: '# BST search for 3', highlight: true }], options: ['2', '1', '3', '5'], correct: 0, explanation: 'Start at 8; 3 is smaller so go left and land on 3 — found. Two nodes. A BST discards half the remaining tree at every step, so a BALANCED tree of a million nodes needs about 20 comparisons. Insert already-sorted data and it degenerates into a linked list at O(n), which is why AVL and red-black trees exist.', hint: 'At each node you go left or right, never both. Count the nodes you actually land on.' },
            { type: 'fillgap', prompt: 'Complete: how deep is this tree?', codeParts: [{ text: 'def depth(node):\n    ', type: 'fixed' }, { text: 'if not node: return 0', type: 'gap', id: 'g1' }, { text: '\n    return 1 + max(depth(node.left), depth(node.right))', type: 'fixed' }], bank: ['if not node: return 0', 'if not node: return 1', 'if not node.left: return 0', 'if node: return 0'], correctFill: { g1: 'if not node: return 0' }, explanation: 'An empty subtree contributes no levels, so it returns 0 and the 1 + on the way back up counts each real node once. Returning 1 for empty over-counts every leaf by one. Checking only node.left crashes the moment node itself is None. And the last option stops immediately, so every tree is depth 0.', hint: 'What is the depth of nothing at all — and what does the 1 + already account for?' },
            { type: 'bug', prompt: 'This BST insert loses nodes. Which line is wrong?', code: [{ text: 'def insert(node, v):', hasError: false }, { text: '    if node is None: return Node(v)', hasError: false }, { text: '    if v < node.v: insert(node.left, v)', hasError: true }, { text: '    else: node.right = insert(node.right, v)', hasError: false }, { text: '    return node', hasError: false }], correctLine: 2, explanation: 'The recursive call builds the new node and RETURNS it, but line 3 throws that return value away — so a left insert vanishes. It needs node.left = insert(node.left, v), matching line 4. This return-and-reassign pattern is how recursive tree building works in a language without pointer-to-pointer.', hint: 'Compare line 3 to line 4. What does one do with the result that the other does not?' },
            { type: 'complexity', prompt: 'Looking up a key a million times', optionA: { code: '# balanced binary search tree\nfound = bst_search(root, key)', label: 'Balanced BST' }, optionB: { code: 'd = {...}\nfound = key in d', label: 'Dict (hash table)' }, correct: 'B', complexityA: 'O(log n)', complexityB: 'O(1)', explanation: 'A hash table jumps straight to a bucket, so lookups do not care how large it is; a balanced tree still halves its way down, about 20 comparisons per million entries. The tree earns its keep elsewhere: it keeps keys in ORDER, so range queries and "next largest" are cheap — questions a dict cannot answer at all without sorting everything first.', hint: 'Both are fast. What does the tree give you that the dict cannot, and is it needed here?' },
            { type: 'realworld', prompt: 'Which traversal prints a tree level by level?', scenario: '🌳 Top row first, then the next row, left to right.', options: [{ code: 'from collections import deque\nq = deque([root])\nwhile q:\n    n = q.popleft()\n    print(n.v)\n    if n.left: q.append(n.left)\n    if n.right: q.append(n.right)', label: 'Queue, breadth-first' }, { code: 'def go(n):\n    if not n: return\n    print(n.v); go(n.left); go(n.right)', label: 'Recursive pre-order' }, { code: 'def go(n):\n    if not n: return\n    go(n.left); go(n.right); print(n.v)', label: 'Recursive post-order' }, { code: 'for v in sorted(values):\n    print(v)', label: 'Sort the values' }], correct: 0, explanation: 'A queue is what makes breadth-first work: every node enqueues its children behind the rest of the current row, so the rows come out in order. The recursive options both go DEPTH-first, diving to a leaf before touching the sibling. Sorting the values loses the shape entirely. Swap the queue for a stack and breadth-first becomes depth-first — one data structure decides the whole traversal.', hint: 'Which structure serves the oldest waiting item first, and why does that produce rows?' },
        ],
        28: [
            { type: 'concept', chapter: 7 },
            { type: 'pair', prompt: 'Match each operation to its cost', pairs: [{ id: 1, left: 'array[i]', right: 'O(1)' }, { id: 2, left: 'Linked list: insert at head', right: 'O(1), two pointers move' }, { id: 3, left: 'BST search, balanced', right: 'O(log n)' }, { id: 4, left: 'Array: insert at front', right: 'O(n), everything shifts' }], explanation: 'Each structure buys one cheap operation by making another expensive: the array\'s O(1) indexing costs it O(n) front-insertion, and the linked list makes the opposite trade. The BST\'s log n carries a hidden condition — "balanced" — which is why self-balancing variants (AVL, red-black) exist at all.' },
        ],
        // ═══ CH8: ALGORITHMS II ⭐⭐⭐⭐ ═══
        29: [
            { type: 'trace', prompt: 'Tower of Hanoi with 3 disks — how many moves?', code: [{ text: 'def hanoi(n):' }, { text: '    if n == 1: return 1' }, { text: '    return 2 * hanoi(n-1) + 1' }, { text: 'print(hanoi(3))', highlight: true }], options: ['3', '5', '7', '8'], correct: 2, explanation: 'Unfold it: hanoi(1)=1, hanoi(2)=3, hanoi(3)=7 — each disk added DOUBLES the work plus one, because you must move the whole smaller tower twice (off the big disk, then back onto it). The closed form is 2ⁿ−1, and that exponential growth is genuine: 64 disks is 2⁶⁴−1 moves, the famous end-of-the-world legend.', hint: 'Compute hanoi(1), then hanoi(2), then hanoi(3), each from the previous.' },
            { type: 'realworld', prompt: 'Which of these problems contains a smaller copy of itself?', scenario: '🤔 Recursion fits when a problem breaks into the same problem, smaller.', options: [{ code: '# a folder contains files and more folders', label: 'Walking a directory tree' }, { code: '# read a file one line at a time until EOF', label: 'Reading lines sequentially' }, { code: '# print "Hi" five times', label: 'Repeating a fixed number of times' }, { code: '# add two numbers together', label: 'A single arithmetic step' }], correct: 0, explanation: 'A folder contains folders, each handled by exactly the same procedure — the structure is self-similar, so the code can be too. The others are flat: reading lines and counting to five are plain iteration, and adding two numbers has no subproblem at all.', hint: 'For each one, ask whether solving it requires solving a smaller version of the identical problem.' },
            { type: 'trace', prompt: 'What does sum_digits(1234) return?', code: [{ text: 'def sum_digits(n):' }, { text: '    if n < 10: return n' }, { text: '    return n%10 + sum_digits(n//10)' }, { text: 'print(sum_digits(1234))', highlight: true }], options: ['10', '1234', '4', '24'], correct: 0, explanation: 'Each level peels the last digit and recurses on the rest: 4 + (3 + (2 + 1)) = 10. The two operators split the work — % 10 extracts, // 10 shrinks toward the base case. 4 is just the first digit peeled; 24 is what you get if you multiply somewhere instead of adding.', hint: 'Write the four levels out: what does each call contribute?' },
            { type: 'output', prompt: 'e is halved on even steps. What is the complexity?', code: [{ text: 'def power(b, e):' }, { text: '    if e == 0: return 1' }, { text: '    if e % 2 == 0:' }, { text: '        h = power(b, e//2)' }, { text: '        return h * h' }, { text: '    return b * power(b, e-1)', highlight: true }], terminalOutput: 'O(log n)', options: ['O(n)', 'O(log n)', 'O(n²)', 'O(1)'], correct: 1, explanation: 'The even branch halves e, and an odd e becomes even after one subtraction — so at least every second step halves, giving O(log e). The crucial detail is computing h ONCE and squaring it: write power(b,e//2) * power(b,e//2) instead and each level doubles its calls, collapsing back to O(e). Same maths, twice the calls, exponentially different cost.', hint: 'How fast does e shrink? And why does saving h into a variable matter so much?' },
            { type: 'scramble', prompt: 'Assemble the recursive binary search', pieces: [{ id: 'a', text: 'def bsearch(arr, t, lo, hi):' }, { id: 'b', text: '    if lo > hi: return -1' }, { id: 'c', text: '    mid = (lo+hi)//2' }, { id: 'd', text: '    if arr[mid] == t: return mid' }, { id: 'e', text: '    elif arr[mid] < t: return bsearch(arr,t,mid+1,hi)' }, { id: 'f', text: '    else: return bsearch(arr,t,lo,mid-1)' }], distractors: [{ id: 'g', text: '    return bsearch(arr,t,lo,hi)' }], correctOrder: ['a', 'b', 'c', 'd', 'e', 'f'], explanation: 'The empty-window check (lo > hi) must come first — it is the base case that makes the recursion terminate. Both recursive calls must EXCLUDE mid, which was just examined. The spare line recurses with identical arguments: same window, same call, RecursionError. Note each call must also be RETURNED — a recursive call whose result is dropped computes the answer and throws it away.', hint: 'Two things every recursion needs: a stopping condition first, and arguments that shrink. Which piece has neither?' },
            { type: 'output', prompt: 'What does this print?', code: [{ text: 'def rev(s):' }, { text: '    if len(s) <= 1: return s' }, { text: '    return rev(s[1:]) + s[0]' }, { text: '' }, { text: 'print(rev("abc"))' }], terminalOutput: 'cba', options: ['cba', 'abc', 'a', 'bca'], correct: 0, explanation: 'Each call peels the first character off and appends it AFTER the reversed remainder — so a ends up last, b second-to-last, and so on. Note the cost: s[1:] copies the rest of the string every call, making this O(n²) despite looking elegant. A two-pointer loop or s[::-1] is linear.', hint: 'Where does s[0] end up relative to the result of the recursive call?' },
            { type: 'bug', prompt: 'This never terminates. Which line is wrong?', code: [{ text: 'def countdown(n):', hasError: false }, { text: '    if n == 0:', hasError: true }, { text: '        return', hasError: false }, { text: '    print(n)', hasError: false }, { text: '    countdown(n - 2)', hasError: false }], correctLine: 1, explanation: 'Starting from an odd number the sequence goes 5, 3, 1, -1, -3 … and never lands exactly on 0, so the base case is missed and the recursion runs until Python stops it. Either test n <= 0, or guarantee the step always hits the case. Base cases must be reachable from EVERY starting value, not just the convenient ones.', hint: 'Trace countdown(5). Does n ever equal exactly 0?' },
            { type: 'trace', prompt: 'How many calls does this make for n = 4?', code: [{ text: 'def hanoi(n, a, b, c):' }, { text: '    if n == 0: return' }, { text: '    hanoi(n-1, a, c, b)' }, { text: '    print(a, "->", c)' }, { text: '    hanoi(n-1, b, a, c)', highlight: true }], options: ['15 moves printed', '4 moves printed', '8 moves printed', '16 moves printed'], correct: 0, explanation: 'Each level does two recursive calls plus one move, giving 2^n - 1 = 15 moves for four discs. Doubling the discs squares the work: 64 discs is about 1.8 × 10^19 moves, the reason the legend says the world ends first. The 16 answer is the classic off-by-one — it is 2^n minus one, because the empty case prints nothing.', hint: 'Each disc roughly doubles the moves. Compute 2^4, then account for the base case printing nothing.' },
            { type: 'complexity', prompt: 'Summing 1..n', optionA: { code: 'def total(n):\n    if n == 0: return 0\n    return n + total(n - 1)', label: 'Recursive' }, optionB: { code: 'def total(n):\n    return n * (n + 1) // 2', label: 'Closed formula' }, correct: 'B', complexityA: 'O(n) time, O(n) stack', complexityB: 'O(1)', explanation: 'The recursion is linear in time AND in memory, because every pending call holds a frame — past about a thousand it raises RecursionError, and Python does not eliminate tail calls. The formula answers in one multiplication regardless of n. Recursion is for problems with recursive STRUCTURE; arithmetic sequences already have an answer.', hint: 'The recursive version uses time. What else does it use, and what happens when n is a million?' },
            { type: 'realworld', prompt: 'Which one totals a nested list of any depth?', scenario: '📦 [1, [2, [3, 4]], 5] should give 15.', options: [{ code: 'def total(x):\n    if isinstance(x, list):\n        return sum(total(i) for i in x)\n    return x', label: 'Recurse on lists' }, { code: 'sum(x)', label: 'Built-in sum' }, { code: 'sum(i for i in x if isinstance(i, int))', label: 'Sum the integers' }, { code: 'len(x)', label: 'Length' }], correct: 0, explanation: 'The depth is unknown, so the shape of the solution has to match the shape of the data: recurse whenever you meet a list, return the number otherwise. Plain sum raises TypeError trying to add a list to an int. Filtering to ints silently returns 6, dropping everything nested — a wrong answer with no error, which is worse. len gives 3.', hint: 'You do not know how deep the nesting goes. What kind of solution can handle any depth?' },
        ],
        30: [
            { type: 'algostep', prompt: 'Merging sorted [1,3,5] and [2,4,6]', array: [1, 3, 5, 2, 4, 6], step: 1, description: 'Both lists are sorted. Compare the two FRONTS: 1 vs 2 — take 1.', question: 'Which comparison happens next?', options: ['3 vs 2', '1 vs 2', '5 vs 6', '3 vs 4'], correct: 0, explanation: 'Taking 1 advances only the LEFT pointer, so the fronts are now 3 and 2. Merge never looks deeper than the two fronts — that is why it is O(n) total: each comparison retires exactly one element. This only works because both inputs are already sorted; the front is guaranteed to be each list\'s minimum.', hint: 'Only the list that surrendered an element advances. What are the two fronts now?' },
            { type: 'trace', prompt: 'log n levels, O(n) work per level — total?', code: [{ text: '# splitting halves the array: log₂(n) levels deep' }, { text: '# merging touches every element once per level: O(n)' }, { text: '# total = levels × work per level = ?', highlight: true }], options: ['O(n)', 'O(n²)', 'O(n log n)', 'O(log n)'], correct: 2, explanation: 'log n levels times n work per level is n log n — the multiplication IS the analysis. This shape generalises: any divide-and-conquer that halves and does linear work per level lands on n log n. Picking O(n) counts one level only; O(log n) counts the levels but forgets the merging.', hint: 'Two numbers are given. The answer is what you do with them.' },
            { type: 'scramble', prompt: 'Assemble the merge step', pieces: [{ id: 'a', text: 'def merge(left, right):' }, { id: 'b', text: '    result = []; i = j = 0' }, { id: 'c', text: '    while i<len(left) and j<len(right):' }, { id: 'd', text: '        if left[i]<=right[j]: result.append(left[i]); i+=1' }, { id: 'e', text: '        else: result.append(right[j]); j+=1' }, { id: 'f', text: '    result += left[i:] + right[j:]' }, { id: 'g', text: '    return result' }], distractors: [{ id: 'h', text: '    return left + right' }], correctOrder: ['a', 'b', 'c', 'd', 'e', 'f', 'g'], explanation: 'The tail line (result += left[i:] + right[j:]) is not optional: the while stops when ONE list empties, and the other still has elements — all guaranteed larger than everything taken so far. Forgetting it silently drops data. The <= rather than < is what makes merge sort stable. The spare line just concatenates without comparing: [1,3,5,2,4,6].', hint: 'When the while exits, what state are the two lists in? Something is left over — where does it go?' },
            { type: 'pair', prompt: 'Match each algorithm to its divide step', pairs: [{ id: 1, left: 'Merge sort', right: 'Split in half, sort both' }, { id: 2, left: 'Quick sort', right: 'Partition around a pivot' }, { id: 3, left: 'Binary search', right: 'Discard half each probe' }, { id: 4, left: 'Strassen', right: 'Split matrices into blocks' }], explanation: 'Same family, different divide: merge sort splits by POSITION and does its work while combining; quicksort splits by VALUE and does its work while dividing, so its combine step is free. Binary search is the degenerate case — it divides but only ever keeps one half, which is why it is log n rather than n log n.' },
            { type: 'output', prompt: 'How many levels deep does merge sort recurse on 8 items?', code: [{ text: 'def msort(a):' }, { text: '    if len(a) <= 1: return a' }, { text: '    mid = len(a) // 2' }, { text: '    return merge(msort(a[:mid]), msort(a[mid:]))' }, { text: '' }, { text: '# a has 8 elements' }], terminalOutput: '3', options: ['3', '8', '4', '2'], correct: 0, explanation: '8 splits to 4, then 2, then 1 — three levels of halving, which is log2(8). Each level does O(n) work merging, so the total is the familiar n log n. Doubling to 16 items adds exactly one level, which is why merge sort scales so gently.', hint: 'How many times can you halve 8 before you reach 1?' },
            { type: 'bug', prompt: 'This merge sort loses elements. Which line is wrong?', code: [{ text: 'def msort(a):', hasError: false }, { text: '    if len(a) <= 1: return a', hasError: false }, { text: '    mid = len(a) // 2', hasError: false }, { text: '    left = msort(a[:mid])', hasError: false }, { text: '    right = msort(a[mid + 1:])', hasError: true }], correctLine: 4, explanation: 'The left half is a[:mid], which stops BEFORE mid — so mid itself belongs to the right half and a[mid + 1:] skips it. The halves must partition the list with no gap and no overlap: a[:mid] and a[mid:]. Off-by-one at a split point silently drops one element per level, so the output is short and sorted, which hides the bug beautifully.', hint: 'Is index mid included in a[:mid]? Then which half should own it?' },
            { type: 'complexity', prompt: 'Sorting: merge sort against a nested-loop sort', optionA: { code: '# compare every pair\nfor i in range(n):\n    for j in range(n):\n        ...', label: 'Nested loops' }, optionB: { code: '# split, sort halves, merge\nmsort(a)', label: 'Merge sort' }, correct: 'B', complexityA: 'O(n²)', complexityB: 'O(n log n)', explanation: 'Divide and conquer wins because splitting costs nothing and merging is linear, so the total is (levels) × (work per level) = log n × n. The trade is memory: merge sort needs an O(n) buffer, which is why quicksort — in place, same average speed — is often preferred when memory is tight and the worst case can be randomised away.', hint: 'How many levels does the halving create, and how much work happens on each?' },
            { type: 'realworld', prompt: 'Which problems fit divide and conquer?', scenario: '🪓 Split the input, solve the parts, combine.', options: [{ code: '# merge sort, quicksort,\n# binary search, closest pair', label: 'Splittable, combinable' }, { code: '# read a config file', label: 'Sequential I/O' }, { code: '# increment a counter', label: 'Single operation' }, { code: '# print a fixed banner', label: 'No input at all' }], correct: 0, explanation: 'The pattern needs two things: a split that makes genuinely smaller subproblems of the SAME kind, and a combine step cheaper than solving from scratch. Sorting and searching have both. Reading a file sequentially has no meaningful split, and the last two have no subproblems at all — dividing them creates work rather than saving it.', hint: 'What must be true about the pieces for splitting to be worth anything?' },
            { type: 'fillgap', prompt: 'Complete the base case for merge sort', codeParts: [{ text: 'def msort(a):\n    ', type: 'fixed' }, { text: 'if len(a) <= 1: return a', type: 'gap', id: 'g1' }, { text: '\n    mid = len(a) // 2\n    return merge(msort(a[:mid]), msort(a[mid:]))', type: 'fixed' }], bank: ['if len(a) <= 1: return a', 'if len(a) == 0: return a', 'if len(a) <= 1: return []', 'if len(a) <= 2: return a'], correctFill: { g1: 'if len(a) <= 1: return a' }, explanation: 'A list of one element is already sorted, so it is returned unchanged — and that also covers the empty case. Stopping only at 0 recurses forever on a single element: mid becomes 0, so one half stays the full list. Returning [] throws the data away. And stopping at 2 leaves an unsorted pair, since nothing ever compares them.', hint: 'Try each candidate on a one-element list. Which ones recurse forever or lose data?' },
            { type: 'trace', prompt: 'Quicksort picks 5 as the pivot on [7, 2, 9, 5, 1]. What are the partitions?', code: [{ text: 'a = [7, 2, 9, 5, 1]' }, { text: 'pivot = 5' }, { text: '# smaller | pivot | larger', highlight: true }], options: ['[2, 1] | 5 | [7, 9]', '[1, 2] | 5 | [7, 9]', '[7, 2] | 5 | [9, 1]', '[2, 1, 5] | [7, 9]'], correct: 0, explanation: 'Partitioning only asks "smaller or larger than the pivot" — it does not sort within the groups, so 2 and 1 keep the order they appeared in. The recursive calls sort them afterwards. The second option is the SORTED left half, which is the state after recursing, not after partitioning: getting these two confused is what makes quicksort traces go wrong.', hint: 'Partitioning asks one yes-or-no question per element. Does it reorder within a group?' },
        ],
        31: [
            { type: 'trace', prompt: 'How many times is fib() entered for fib(5), no memo?', code: [{ text: 'def fib(n):' }, { text: '    if n<=1: return n' }, { text: '    return fib(n-1)+fib(n-2)' }, { text: '# count every call in the tree for fib(5)', highlight: true }], options: ['5', '9', '15', '25'], correct: 2, explanation: 'Count bottom-up: calls(0)=1, calls(1)=1, then calls(n)=1+calls(n-1)+calls(n-2) → 3, 5, 9, 15. Fifteen calls to compute six values — fib(1) alone is entered five times. That redundancy is the whole case for memoisation, which collapses the tree to one call per distinct n: six.', hint: 'Build a small table: how many calls does fib(2) take? fib(3)? Each row uses the two before it.' },
            { type: 'refactor', prompt: 'Which rewrite stops recomputing the same values?', originalCode: 'def fib(n):\n    if n<=1: return n\n    return fib(n-1)+fib(n-2)', options: [{ code: 'memo = {}\ndef fib(n):\n    if n in memo: return memo[n]\n    if n<=1: return n\n    memo[n] = fib(n-1)+fib(n-2)\n    return memo[n]', label: 'Cache results in a dict' }, { code: 'def fib(n):\n    return n if n<=1 else fib(n-1)+fib(n-2)', label: 'Compress to one line' }, { code: 'def fib(n):\n    a, b = 0, 1\n    for _ in range(n):\n        a, b = b, a+b\n    return b', label: 'Iterate with two variables' }], correct: 0, explanation: 'The memo makes each distinct n computed once — O(n) time. The one-liner is the SAME algorithm in fewer characters; syntax does not change complexity. The iterative version is genuinely O(n) too and uses O(1) space — but read it carefully: it returns b, which is fib(n+1). Off by one exactly at the boundary, the hardest place to notice. The memo version is the one that is both fast and correct as written.', hint: 'Two of these are fast. Run the iterative one by hand for n=0 and n=1 before trusting it.' },
            { type: 'realworld', prompt: 'What is the fewest coins that make 6 from [1, 3, 4]?', scenario: '💰 Coins: [1, 3, 4]. Target: 6. Take the biggest coin first and see where it lands you.', options: [{ code: '3 + 3 = 6', label: '2 coins' }, { code: '4 + 1 + 1 = 6', label: '3 coins' }, { code: '4 + 3 = 7', label: '2 coins, overshoots' }, { code: '1 * 6 = 6', label: '6 coins' }], correct: 0, explanation: 'Taking the largest coin first (greedy) grabs 4, then can only finish with 1+1 — three coins. Skipping the 4 entirely gives 3+3, two coins. This is exactly why coin change needs DP: the locally best choice is not globally best. Greedy only happens to work on "canonical" systems like [1,5,10,25].', hint: 'Try it once starting from the 4, and once ignoring the 4.' },
            { type: 'fillgap', prompt: 'Each step comes from 1 or 2 below — fill the recurrence', codeParts: [{ text: 'def climb(n):\n    if n<=2: return n\n    dp = [0]*(n+1)\n    dp[1], dp[2] = 1, 2\n    for i in range(3, n+1):\n        ', type: 'fixed' }, { text: 'dp[i] = dp[i-1] + dp[i-2]', type: 'gap', id: 'g1' }, { text: '\n    return dp[n]', type: 'fixed' }], bank: ['dp[i] = dp[i-1] + dp[i-2]', 'dp[i] = dp[i-1] * 2', 'dp[i] = i', 'dp[i] = dp[i-1]'], correctFill: { g1: 'dp[i] = dp[i-1] + dp[i-2]' }, explanation: 'You arrive at step i from i-1 (one step) or i-2 (a double) — and those two pools of routes are disjoint, so they ADD. Doubling overcounts: it pretends every route to i-1 splits in two, but a route ending in a double-step never passes through i-1 at all. dp[i]=i counts steps, not routes.', hint: 'From where can you reach step i in exactly one move? Combine the ways of getting to THOSE places.' },
            { type: 'trace', prompt: 'Extend the table: how many ways up 5 stairs?', code: [{ text: '# ways(1)=1, ways(2)=2' }, { text: '# ways(3)=ways(2)+ways(1)=3' }, { text: '# ways(4)=ways(3)+ways(2)=5' }, { text: '# ways(5)=ways(4)+ways(3)=?', highlight: true }], options: ['5', '7', '8', '13'], correct: 2, explanation: '5 + 3 = 8. It is Fibonacci wearing a costume — same recurrence, shifted start. Most counting-paths problems reduce to a known recurrence like this; recognising the shape saves deriving it from scratch. 13 is one step further (n=6), the classic off-by-one.', hint: 'The last two rows are on screen. Add them.' },
            { type: 'output', prompt: 'How many fib calls does the cached version make for n = 30?', code: [{ text: 'from functools import lru_cache' }, { text: '' }, { text: '@lru_cache(maxsize=None)' }, { text: 'def fib(n):' }, { text: '    if n < 2: return n' }, { text: '    return fib(n-1) + fib(n-2)' }], terminalOutput: '31', options: ['31', '1664079', '30', '900'], correct: 0, explanation: 'Each distinct n is computed once and served from the cache after that — 31 calls for 0 through 30, versus 2,692,537 without the decorator. Memoisation does not change the algorithm at all; it changes the number of times the algorithm runs, turning exponential into linear with one line.', hint: 'With a cache, how many DIFFERENT values of n can fib actually be asked about?' },
            { type: 'bug', prompt: 'This cache never hits. Which line is wrong?', code: [{ text: 'cache = {}', hasError: false }, { text: 'def fib(n):', hasError: false }, { text: '    if n < 2: return n', hasError: false }, { text: '    r = fib(n-1) + fib(n-2)', hasError: false }, { text: '    cache[n] = r', hasError: true }, { text: '    return r', hasError: false }], correctLine: 4, explanation: 'The result is stored but never READ — there is no `if n in cache: return cache[n]` before the work, so every call recomputes and the dict just grows. A cache is two halves: check before, store after. Writing only the store half is the most common memoisation mistake, and it looks completely reasonable in review.', hint: 'The cache is written on line 5. Where is it ever read?' },
            { type: 'complexity', prompt: 'Fibonacci: plain recursion against memoised', optionA: { code: 'def fib(n):\n    if n < 2: return n\n    return fib(n-1) + fib(n-2)', label: 'Plain recursion' }, optionB: { code: '@lru_cache(maxsize=None)\ndef fib(n):\n    if n < 2: return n\n    return fib(n-1) + fib(n-2)', label: 'Memoised' }, correct: 'B', complexityA: 'O(2ⁿ)', complexityB: 'O(n)', explanation: 'The plain version recomputes the same subtrees over and over — fib(30) takes about 2.7 million calls, and fib(50) would take days. The cache makes each n cost one computation, so the whole call tree collapses to a line. Same code, one decorator, exponential to linear.', hint: 'How many times does the uncached version compute fib(10) on its way to fib(30)?' },
            { type: 'trace', prompt: 'What does dp hold after this loop?', code: [{ text: 'dp = [0, 1]' }, { text: 'for i in range(2, 6):' }, { text: '    dp.append(dp[i-1] + dp[i-2])' }, { text: 'print(dp)', highlight: true }], options: ['[0, 1, 1, 2, 3, 5]', '[0, 1, 1, 2, 3]', '[0, 1, 2, 3, 5, 8]', '[1, 1, 2, 3, 5, 8]'], correct: 0, explanation: 'This is the same recurrence built BOTTOM-UP: start from the known answers and work forward, so nothing is ever recomputed and there is no call stack to overflow. Tabulation and memoisation compute identical values; the difference is direction, and bottom-up wins when every subproblem is needed anyway.', hint: 'Write out dp after each pass. The loop runs for i = 2, 3, 4, 5.' },
            { type: 'realworld', prompt: 'Which problems does dynamic programming actually fit?', scenario: '🧩 When is a cache the right tool?', options: [{ code: '# fewest coins that make 63p\n# from {1, 5, 10, 25}', label: 'Coin change' }, { code: '# reverse a list', label: 'Reverse a list' }, { code: '# merge sort a list', label: 'Merge sort' }, { code: '# find the largest element', label: 'Find the maximum' }], correct: 0, explanation: 'Coin change asks the same question over and over — the best way to make 38p comes up on many different paths — so caching it collapses the work. That is overlapping subproblems plus optimal substructure, the two conditions DP needs. Merge sort is the instructive wrong answer: it HAS substructure but its halves never overlap, so a cache would never hit. Reversing and finding a maximum are single linear passes with no subproblems to reuse.', hint: 'Merge sort splits into subproblems too. Which of these asks the SAME smaller question more than once?' },
            { type: 'refactor', prompt: 'Which computes fib(n) in constant memory?', originalCode: 'dp = [0] * (n + 1)\ndp[1] = 1\nfor i in range(2, n + 1):\n    dp[i] = dp[i-1] + dp[i-2]\nreturn dp[n]', options: [{ code: 'a, b = 0, 1\nfor _ in range(n):\n    a, b = b, a + b\nreturn a', label: 'Two rolling variables' }, { code: 'return fib(n - 1) + fib(n - 2)', label: 'Plain recursion' }, { code: 'return sorted([fib(i) for i in range(n)])[-1]', label: 'Sort the sequence' }], correct: 0, explanation: 'Only the last two values are ever read, so the whole table is unnecessary — two variables give O(1) space instead of O(n). This "rolling array" trick applies to most one-dimensional DP. The recursion is exponential and has no base case here; the third computes every value, sorts them, and is worse than what it replaced.', hint: 'The loop reads dp[i-1] and dp[i-2]. How much of the table does it ever actually touch?' },
        ],
        32: [
            { type: 'trace', prompt: 'What does power(2, 10) return?', code: [{ text: 'def power(b, e):' }, { text: '    if e==0: return 1' }, { text: '    if e%2==0: h=power(b,e//2); return h*h' }, { text: '    return b*power(b,e-1)' }, { text: 'print(power(2, 10))', highlight: true }], options: ['20', '100', '512', '1024'], correct: 3, explanation: '2¹⁰ = 1024 — the algorithm changes the route, not the value: power(2,10) squares power(2,5), and so on down. 20 is 2×10 (mistaking power for multiplication), 100 is 10², and 512 is 2⁹, one halving misplaced. Knowing 2¹⁰ ≈ 10³ is independently useful: it is why 1 KB is 1024 bytes.', hint: 'The recursion computes 2 to the 10th, just cleverly. What IS 2¹⁰?' },
            { type: 'output', prompt: 'Six calls for e=10. What growth is that?', code: [{ text: '# power(2,10) → power(2,5) → power(2,4)' }, { text: '# → power(2,2) → power(2,1) → power(2,0)' }, { text: '# e went 10 → 5 → 4 → 2 → 1 → 0', highlight: true }], terminalOutput: 'O(log n)', options: ['O(n)', 'O(log n)', 'O(n²)', 'O(1)'], correct: 1, explanation: 'Six calls for e=10, and doubling e adds only about one more call — that is the signature of O(log n). The odd steps (10→5 is a halving, 5→4 a subtraction) at most double the count, which a constant factor absorbs. Naive power would make ten calls, one per multiplication.', hint: 'If e were 20, how many more calls? What about e = 1000?' },
            { type: 'scramble', prompt: 'Assemble the memoised fibonacci', pieces: [{ id: 'a', text: 'memo = {}' }, { id: 'b', text: 'def fib(n):' }, { id: 'c', text: '    if n in memo: return memo[n]' }, { id: 'd', text: '    if n <= 1: return n' }, { id: 'e', text: '    memo[n] = fib(n-1) + fib(n-2)' }, { id: 'f', text: '    return memo[n]' }], distractors: [{ id: 'g', text: '    return fib(n)' }], correctOrder: ['a', 'b', 'c', 'd', 'e', 'f'], explanation: 'The memo check comes first — that is the fast path that makes repeated calls free. The result must be STORED before returning (line e): compute-and-return without storing is the whole bug memoisation exists to fix, and the code still gives right answers slowly, which makes it nasty to catch. The spare line calls fib(n) with the same n: infinite recursion.', hint: 'Which line makes the SECOND call to fib(3) cheap? Without the store, what changed?' },
            { type: 'realworld', prompt: 'Fib benefits from DP; merge sort does not. What is the difference?', scenario: '🧠 Both recurse. Only one is worth caching.', options: [{ code: '# fib(n-1) and fib(n-2) RESHARE subcalls\n# merge sort halves never overlap', label: 'Overlapping subproblems' }, { code: '# fib is arithmetic, sorting is not', label: 'Arithmetic vs rearranging' }, { code: '# fib recurses twice, merge sort once', label: 'Number of recursive calls' }, { code: '# fib is defined on integers', label: 'Integer inputs' }], correct: 0, explanation: 'Caching pays only when the same subproblem RECURS: fib(5) and fib(4) both need fib(3), so storing it saves work. Merge sort\'s halves are disjoint — no subarray is ever sorted twice, so a cache would only ever miss. That plus optimal substructure (optimal whole from optimal parts) is the two-part test for DP. Merge sort also recurses twice, which kills the third option.', hint: 'A cache helps only if something is asked twice. Which algorithm ever repeats a subproblem?' },
            { type: 'output', prompt: 'What does this print?', code: [{ text: 'def perms(s):' }, { text: '    if len(s) <= 1: return [s]' }, { text: '    out = []' }, { text: '    for i, c in enumerate(s):' }, { text: '        for p in perms(s[:i] + s[i+1:]):' }, { text: '            out.append(c + p)' }, { text: '    return out' }, { text: '' }, { text: 'print(len(perms("abcd")))' }], terminalOutput: '24', options: ['24', '4', '16', '12'], correct: 0, explanation: 'Every position can host every remaining character, so the count is n factorial — 4! = 24. Factorial growth is brutal: 10 characters is 3.6 million and 15 is over a trillion, which is why permutation search is only viable on tiny inputs and why the travelling salesman problem is hard.', hint: 'Four choices for the first character, then three for the next. Keep multiplying.' },
            { type: 'bug', prompt: 'This flatten crashes on deep input. Which line is the real problem?', code: [{ text: 'def flatten(x):', hasError: false }, { text: '    out = []', hasError: false }, { text: '    for i in x:', hasError: false }, { text: '        if isinstance(i, list): out += flatten(x)', hasError: true }, { text: '        else: out.append(i)', hasError: false }, { text: '    return out', hasError: false }], correctLine: 3, explanation: 'The recursive call passes x — the whole list — instead of i, the nested element. So it never gets smaller and recurses until Python stops it. The subproblem must be strictly smaller than the problem; passing the same argument back is the fastest way to guarantee it is not.', hint: 'What is being passed to the recursive call, and is it smaller than what came in?' },
            { type: 'complexity', prompt: 'Checking every subset of n items', optionA: { code: 'for mask in range(2 ** n):\n    ...', label: 'All subsets' }, optionB: { code: 'for x in items:\n    ...', label: 'One pass' }, correct: 'B', complexityA: 'O(2ⁿ)', complexityB: 'O(n)', explanation: 'Each item is either in or out, so n items give 2^n subsets — 30 items is a billion, 50 is a quadrillion. Exhaustive subset search is only practical below about 25 items; past that you need DP over states, greedy with a proof, or an approximation. Knowing WHICH exponential you are looking at (2^n for subsets, n! for orderings) tells you how small the input has to be.', hint: 'Each item is in or out. How many combinations of those choices exist?' },
            { type: 'errordecode', prompt: 'Decode this error', errorText: 'Traceback (most recent call last):\n  File "main.py", line 3, in solve\n    return solve(n) + 1\n  File "main.py", line 3, in solve\n    return solve(n) + 1\n  [Previous line repeated 996 more times]\nRecursionError: maximum recursion depth exceeded', question: 'What is wrong?', options: ['The recursive call passes n unchanged, so the input never shrinks', 'The base case returns the wrong type', 'The recursion limit is too low', 'It should return n + 1'], correct: 0, explanation: 'solve(n) calls solve(n) — the argument never changes, so no base case can ever be reached no matter what it tests. This is different from a MISSING base case: here the guard may be perfectly correct and simply unreachable. Every recursive call must move the argument toward the base case.', hint: 'Look at what the call passes. Is it different from what the function received?' },
            { type: 'fillgap', prompt: 'Complete: binary search, recursively', codeParts: [{ text: 'def bs(a, t, lo, hi):\n    ', type: 'fixed' }, { text: 'if lo > hi: return -1', type: 'gap', id: 'g1' }, { text: '\n    mid = (lo + hi) // 2\n    if a[mid] == t: return mid\n    if a[mid] < t: return bs(a, t, mid + 1, hi)\n    return bs(a, t, lo, mid - 1)', type: 'fixed' }], bank: ['if lo > hi: return -1', 'if lo >= hi: return -1', 'if lo > hi: return mid', 'if lo == hi: return -1'], correctFill: { g1: 'if lo > hi: return -1' }, explanation: 'The range is empty exactly when lo passes hi, and -1 is the conventional "not found". Using >= stops while one element is still unchecked, so a value sitting there is reported missing. Returning mid is a NameError — it does not exist yet. And == misses the case where lo overshoots hi by more than one.', hint: 'When is the search range genuinely empty — and is a single remaining element empty?' },
            { type: 'realworld', prompt: 'Which one counts files in a folder tree of unknown depth?', scenario: '📂 Folders inside folders, no depth limit.', options: [{ code: 'def count(d):\n    n = 0\n    for e in d.entries:\n        n += count(e) if e.is_dir else 1\n    return n', label: 'Recurse into folders' }, { code: 'len(d.entries)', label: 'Top-level count' }, { code: 'sum(1 for e in d.entries if not e.is_dir)', label: 'Files at this level' }, { code: 'len(d.entries) * depth', label: 'Multiply by depth' }], correct: 0, explanation: 'The data is a tree of unknown depth, so the solution has to have the same shape: recurse into directories, count files. The other three all stop at the top level — and the multiplication is guesswork that happens to give a number, which is the worst kind of wrong because nothing signals it.', hint: 'The folders nest arbitrarily deep. Which option ever looks inside one?' },
        ],
        // ═══ CH9: ADVANCED ⭐⭐⭐⭐ ═══
        33: [
            { type: 'pair', prompt: 'Match each graph term to what it means', pairs: [{ id: 1, left: 'Adjacency list', right: 'Each node maps to its neighbours' }, { id: 2, left: 'Adjacency matrix', right: 'n×n grid of 0/1' }, { id: 3, left: 'Directed', right: 'Edges point one way' }, { id: 4, left: 'Undirected', right: 'Edges go both ways' }], explanation: 'The list-versus-matrix choice is a space/speed trade: the list stores only edges that exist — O(V+E), ideal for sparse graphs — while the matrix burns O(V²) space to answer "is there an edge?" in O(1). Most real graphs (social, road, web) are sparse, which is why the adjacency list is the default.' },
            { type: 'realworld', prompt: 'Which of these is naturally a graph?', scenario: '🌍 Nodes and edges should map onto real things.', options: [{ code: '# users are nodes, friendships are edges', label: 'A social network' }, { code: '# tasks done one after another', label: 'A to-do list' }, { code: '# one running total', label: 'A counter' }, { code: '# folders inside folders', label: 'A directory tree' }], correct: 0, explanation: 'A social network is the canonical graph: many-to-many relations, cycles allowed, no root. The list and counter have no relations to model at all. The directory tree is the instructive near-miss — it IS a graph, but a restricted one (connected, acyclic, one parent each), and that restriction is exactly what the word "tree" means.', hint: 'One of these has relations but with a no-cycles, one-parent rule. Which is the unrestricted one?' },
            { type: 'output', prompt: 'What does len(graph["A"]) count?', code: [{ text: 'graph = {' }, { text: '    "A": ["B", "C"],' }, { text: '    "B": ["C"],' }, { text: '    "C": []' }, { text: '}' }, { text: 'print(len(graph["A"]))' }], terminalOutput: '2', options: ['1', '2', '3', '0'], correct: 1, explanation: 'graph["A"] is A\'s neighbour list — ["B","C"] — so its length is A\'s out-degree: 2. Counting 3 means counting the graph\'s nodes instead of A\'s edges. In a directed graph the list holds only OUTGOING edges, which is why C\'s list is empty even though two edges point at it.', hint: 'The dict maps node → outgoing neighbours. Whose list is being measured?' },
            { type: 'trace', prompt: 'Six list entries — how many actual edges?', code: [{ text: 'graph = {"A": ["B","C"],' }, { text: '         "B": ["A","C"],' }, { text: '         "C": ["A","B"]}' }, { text: '# undirected: A--B, A--C, B--C' }, { text: '# entries across all lists: 6', highlight: true }], options: ['3', '6', '2', '9'], correct: 0, explanation: 'An undirected edge A--B appears in BOTH lists — under A and under B — so the six entries describe three edges: entries ÷ 2. This double-count bites in real code whenever you sum len() over an adjacency list to count edges; the handshake lemma (Σ degrees = 2E) is the same fact in formal dress.', hint: 'Each edge is written down twice, once from each end. Divide.' },
            { type: 'output', prompt: 'How many EDGES does this graph have?', code: [{ text: 'g = {' }, { text: '    "A": ["B", "C"],' }, { text: '    "B": ["A", "D"],' }, { text: '    "C": ["A"],' }, { text: '    "D": ["B"],' }, { text: '}' }, { text: 'print(sum(len(v) for v in g.values()) // 2)' }], terminalOutput: '3', options: ['3', '6', '4', '8'], correct: 0, explanation: 'Every undirected edge appears in BOTH adjacency lists, so the six entries describe three edges: A-B, A-C, B-D. That doubling is why the code divides by 2 — and why a directed graph, where each edge is listed once, would not. Getting this wrong is how you end up reporting twice the traffic on a network.', hint: 'Count the entries, then ask how many times a single connection between two nodes is written down.' },
            { type: 'bug', prompt: 'This walk never terminates on a cyclic graph. What is missing?', code: [{ text: 'def walk(g, node):', hasError: false }, { text: '    print(node)', hasError: false }, { text: '    for nb in g[node]:', hasError: false }, { text: '        walk(g, nb)', hasError: true }, { text: '', hasError: false }], correctLine: 3, explanation: 'With A-B pointing both ways, A visits B which visits A which visits B — forever. A graph walk needs a `visited` set: mark on arrival, skip anything already marked. This is the ONE thing that separates graph traversal from tree traversal, since a tree has no way back to where you came from.', hint: 'A tree version of this code would be fine. What can a graph do that a tree cannot?' },
            { type: 'pair', prompt: 'Match each graph term to what it means', pairs: [{ id: 1, left: 'Vertex', right: 'A node — a thing in the graph' }, { id: 2, left: 'Edge', right: 'A connection between two vertices' }, { id: 3, left: 'Directed', right: 'The connection only goes one way' }, { id: 4, left: 'Weighted', right: 'Each edge carries a cost or distance' }], explanation: 'These four choices describe most real modelling decisions. Followers on social media are directed (following is not mutual); roads with distances are weighted, which is why Dijkstra is needed rather than plain BFS. Get the model wrong and the algorithm answers a question you did not ask.', hint: null },
            { type: 'complexity', prompt: 'Storing a graph with 10,000 vertices and 20,000 edges', optionA: { code: '# adjacency matrix\nm = [[0] * n for _ in range(n)]', label: 'Matrix' }, optionB: { code: '# adjacency list\ng = {v: [] for v in vertices}', label: 'List' }, correct: 'B', complexityA: 'O(V²) space', complexityB: 'O(V + E) space', explanation: 'The matrix needs 10,000² = 100 million cells to hold 20,000 edges — almost all zeros. The list stores only what exists, 30,000 entries. Matrices win on DENSE graphs and when you need instant "is there an edge between these two?"; sparse real-world graphs are the common case, and lists are the common answer.', hint: 'Compare the number of cells the matrix reserves with the number of edges that actually exist.' },
            { type: 'fillgap', prompt: 'Complete: add an undirected edge', codeParts: [{ text: 'def add_edge(g, a, b):\n    g[a].append(b)\n    ', type: 'fixed' }, { text: 'g[b].append(a)', type: 'gap', id: 'g1' }, { text: '', type: 'fixed' }], bank: ['g[b].append(a)', 'g[a].append(a)', 'g[b].append(b)', 'return g[a]'], correctFill: { g1: 'g[b].append(a)' }, explanation: 'Undirected means the connection is mutual, so it has to be recorded from both sides — otherwise a walk starting at b would never find a. Leaving this line out builds a DIRECTED graph while you believe you built an undirected one, and the bug shows up much later as a traversal that mysteriously misses half the graph.', hint: 'Line 2 records the edge from a. Who else needs to know about it?' },
            { type: 'realworld', prompt: 'Which model fits "who follows whom"?', scenario: '📱 Alice follows Bob. Bob does not follow Alice.', options: [{ code: 'g = {"alice": ["bob"], "bob": []}', label: 'Directed adjacency list' }, { code: 'g = {"alice": ["bob"], "bob": ["alice"]}', label: 'Undirected adjacency list' }, { code: 'users = ["alice", "bob"]', label: 'Flat list of users' }, { code: 'g = {"alice": "bob"}', label: 'One name per user' }], correct: 0, explanation: 'Following is one-way, so the edge is recorded only from alice — a directed graph. The undirected version silently claims Bob follows Alice too, which is a data error, not a modelling shortcut. The flat list keeps no relationships at all, and the last option caps every user at exactly one connection.', hint: 'Is the relationship mutual? And what does each structure claim about Bob?' },
        ],
        34: [
            { type: 'trace', prompt: 'BFS from A — in what order do nodes print?', code: [{ text: '# A→[B,C], B→[D], C→[D], D→[]' }, { text: 'def bfs(start, graph):' }, { text: '    q = deque([start]); seen = {start}' }, { text: '    while q:' }, { text: '        node = q.popleft(); print(node)' }, { text: '        for n in graph[node]:' }, { text: '            if n not in seen:' }, { text: '                seen.add(n); q.append(n)', highlight: true }], options: ['A B C D', 'A B D C', 'A C B D', 'D B C A'], correct: 0, explanation: 'The queue makes it level-by-level: A prints and enqueues B, C; B prints and enqueues D; C prints but D is already seen; D prints. One subtlety carries the correctness: D is marked seen when ENQUEUED, not when printed — mark on dequeue instead and D would enter the queue twice. "A B D C" is DFS, diving before finishing the level.', hint: 'Track the queue contents after each print. Who is waiting, in what order?' },
            { type: 'refactor', prompt: 'Why does cycle detection need THREE node states, not two?', originalCode: '# seen = set()  # one bit per node\n# A→B→C→A ... and also D→B\n# when D reaches B, is that a cycle?', options: [{ code: 'state[n] = EXPLORING while its subtree\nis open, DONE after; a cycle is meeting\nan EXPLORING node again', label: 'Track exploring vs finished' }, { code: 'seen.add(n) on first visit;\na cycle is meeting a seen node', label: 'One visited set' }, { code: 'cycle if edge_count >= node_count', label: 'Compare edges to nodes' }], correct: 0, explanation: 'In a directed graph, reaching an already-visited node is NOT proof of a cycle — D→B re-reaches B along a different route with no way back. A cycle is specifically reaching a node whose exploration is still OPEN: an ancestor of the current path. That is the gray state in white/gray/black. The edge count heuristic fails both ways — a diamond has cycles-free extra edges, and a self-loop cycles with e < n.', hint: 'Draw A→B→C plus D→B. The visited set flags B twice. Is there any cycle?' },
            { type: 'realworld', prompt: 'Unweighted maze, need the SHORTEST route. Which traversal?', scenario: '🗺️ Both will find the exit. Only one promises the fewest steps.', options: [{ code: 'bfs(start)  # explore level by level', label: 'Breadth-first' }, { code: 'dfs(start)  # follow one path to its end', label: 'Depth-first' }, { code: 'random_walk(start)', label: 'Random walk' }, { code: 'dijkstra(start)  # with edge weights', label: 'Dijkstra' }], correct: 0, explanation: 'BFS reaches every node at distance 1 before any node at distance 2, so the FIRST time it touches the exit is provably the shortest route. DFS can wander an arbitrarily long path first — it finds A route, not the best one. Dijkstra is not wrong so much as wasteful: with all weights equal it degenerates into BFS with a priority queue it did not need.', hint: 'Which traversal guarantees that distance-k nodes are all reached before any distance-k+1 node?' },
            { type: 'pair', prompt: 'Match each traversal to its machinery and its job', pairs: [{ id: 1, left: 'BFS structure', right: 'A queue' }, { id: 2, left: 'DFS structure', right: 'A stack (or recursion)' }, { id: 3, left: 'BFS strength', right: 'Shortest unweighted path' }, { id: 4, left: 'DFS strength', right: 'Cycle and ordering checks' }], explanation: 'The container IS the algorithm: swap BFS\'s queue for a stack and you literally have iterative DFS — one data structure apart. The queue\'s fairness gives level order (hence shortest paths); the stack\'s depth-first plunge gives the ancestor information that cycle detection and topological sort need.' },
            { type: 'output', prompt: 'Starting at A, what order does BFS visit?', code: [{ text: '# A - B, A - C, B - D, C - D' }, { text: 'from collections import deque' }, { text: 'q = deque(["A"]); seen = {"A"}' }, { text: 'while q:' }, { text: '    n = q.popleft(); print(n, end=" ")' }, { text: '    for nb in g[n]:' }, { text: '        if nb not in seen: seen.add(nb); q.append(nb)' }], terminalOutput: 'A B C D', options: ['A B C D', 'A B D C', 'A C B D', 'A D B C'], correct: 0, explanation: 'BFS takes from the FRONT, so everything one step from A comes out before anything two steps away — A, then B and C, then D. That is exactly why BFS finds the shortest path in an unweighted graph: it cannot reach distance 2 before finishing distance 1. Swap popleft for pop and you get DFS, A B D C.', hint: 'Which end does popleft take from, and what does that mean for how far a node is from A?' },
            { type: 'bug', prompt: 'This BFS visits some nodes twice. Which line is wrong?', code: [{ text: 'q = deque([start]); seen = set()', hasError: false }, { text: 'while q:', hasError: false }, { text: '    n = q.popleft()', hasError: false }, { text: '    seen.add(n)', hasError: true }, { text: '    for nb in g[n]:', hasError: false }, { text: '        if nb not in seen: q.append(nb)', hasError: false }], correctLine: 3, explanation: 'Marking on DEQUEUE is too late: a node with two neighbours already in the queue gets enqueued twice before either is processed. Mark when you ENQUEUE instead — add to seen at the same moment you append. The queue then holds each node at most once, which also bounds its size at V.', hint: 'Between being added to the queue and being taken out, is a node protected from being added again?' },
            { type: 'trace', prompt: 'Starting at A, what order does DFS visit?', code: [{ text: '# A - B, A - C, B - D' }, { text: 'def dfs(n, seen=None):' }, { text: '    seen = seen or set()' }, { text: '    if n in seen: return' }, { text: '    seen.add(n); print(n, end=" ")' }, { text: '    for nb in g[n]: dfs(nb, seen)', highlight: true }], options: ['A B D C', 'A B C D', 'A C B D', 'A D C B'], correct: 0, explanation: 'DFS commits to a branch: from A it goes to B, from B all the way to D, and only when that path is exhausted does it come back for C. Breadth-first would have taken B and C first. Depth-first uses O(depth) memory rather than O(width), which is why it wins on wide graphs and loses on deep ones — where it overflows the stack.', hint: 'After visiting B, does the algorithm go back to A for C, or keep going deeper?' },
            { type: 'complexity', prompt: 'Shortest path in an UNWEIGHTED graph', optionA: { code: '# try every path, keep the shortest\nall_paths(g, a, b)', label: 'Enumerate all paths' }, optionB: { code: '# BFS from a, stop at b\nbfs(g, a, b)', label: 'BFS' }, correct: 'B', complexityA: 'exponential', complexityB: 'O(V + E)', explanation: 'BFS reaches every node in increasing distance order, so the first time it touches b it has already found the shortest route — no comparison needed. Enumerating paths explores a number that grows exponentially with the graph. Note the "unweighted" in the question: give the edges different costs and BFS stops being correct, and Dijkstra takes over.', hint: 'BFS finds b once. Why does it not need to check whether a shorter route exists?' },
            { type: 'realworld', prompt: 'Which one finds the fewest moves in a puzzle?', scenario: '🧩 Each move leads to a new state. Find the goal in the fewest moves.', options: [{ code: '# BFS over states', label: 'Breadth-first' }, { code: '# DFS over states', label: 'Depth-first' }, { code: '# sort the states', label: 'Sort states' }, { code: '# random moves until solved', label: 'Random walk' }], correct: 0, explanation: 'Fewest moves is shortest path on the graph of states, and BFS is the algorithm that finds it — it exhausts everything reachable in k moves before trying k+1. DFS will find A solution, usually a badly long one, and may dive forever down an infinite state space. Sorting states means nothing here, and a random walk offers no guarantee at all.', hint: 'Rephrase "fewest moves" as a question about distance. Which traversal answers it?' },
            { type: 'pair', prompt: 'Match each traversal to what it is for', pairs: [{ id: 1, left: 'BFS', right: 'Shortest path in an unweighted graph' }, { id: 2, left: 'DFS', right: 'Cycle detection, topological sort' }, { id: 3, left: 'Dijkstra', right: 'Shortest path with edge weights' }, { id: 4, left: 'Union-Find', right: 'Are these two in the same group?' }], explanation: 'BFS and DFS differ only in queue versus stack, and that one swap changes what the algorithm is GOOD at rather than what it can reach. Dijkstra is BFS with a priority queue, which is what handles weights. Union-Find answers connectivity without traversing at all, in nearly constant time per query.', hint: null },
        ],
        35: [
            { type: 'trace', prompt: 'Two pointers on sorted [1,2,3,4,6], target 6 — where do they stop?', code: [{ text: 'arr = [1, 2, 3, 4, 6]' }, { text: 'lo, hi = 0, 4' }, { text: '# 1+6=7 > 6 → move hi' }, { text: '# 1+4=5 < 6 → move lo' }, { text: '# 2+4=6 → stop', highlight: true }], options: ['indices [1, 3]', 'indices [0, 4]', 'indices [2, 3]', 'no pair exists'], correct: 0, explanation: 'Too big → shrink from the right; too small → grow from the left. The stop is at 2+4, indices [1,3]. The reason discarding is safe is the sorted order: when 1+6 overshoots, 6 is too big for EVERY partner ≥1, so hi can drop without missing anything. That pruning argument is the whole technique — and it dies on unsorted input.', hint: 'Follow the two moves shown, then name the indices (not the values) where the sum hits 6.' },
            { type: 'refactor', prompt: 'Which duplicate check is one pass and leaves the input alone?', originalCode: 'for i in range(len(arr)):\n    for j in range(i+1, len(arr)):\n        if arr[i]==arr[j]: return True', options: [{ code: 'return len(arr) != len(set(arr))', label: 'Compare sizes via a set' }, { code: 'arr.sort()\nfor i in range(len(arr)-1):\n    if arr[i]==arr[i+1]: return True\nreturn False', label: 'Sort, then scan neighbours' }, { code: 'from collections import Counter\nreturn max(Counter(arr).values()) >= 1', label: 'Counter with a threshold' }], correct: 0, explanation: 'Building the set drops duplicates, so a length mismatch is exactly "a duplicate existed" — one O(n) pass, input untouched. The sort version is CORRECT but pays O(n log n) and mutates the caller\'s list, a side effect the function\'s name never advertised. The Counter version has the right idea and the wrong threshold: every count is >= 1, so it returns True for every non-empty input. One character (> for >=) separates it from correct.', hint: 'One option is slower-but-right, one is always-True. Check the threshold carefully.' },
            { type: 'fillgap', prompt: 'Slide the window without re-summing it', codeParts: [{ text: 'def max_sum(arr, k):\n    window = sum(arr[:k])\n    best = window\n    for i in range(k, len(arr)):\n        ', type: 'fixed' }, { text: 'window += arr[i] - arr[i-k]', type: 'gap', id: 'g1' }, { text: '\n        best = max(best, window)\n    return best', type: 'fixed' }], bank: ['window += arr[i] - arr[i-k]', 'window = sum(arr[i-k+1:i+1])', 'window += arr[i]', 'window = arr[i]'], correctFill: { g1: 'window += arr[i] - arr[i-k]' }, explanation: 'One element enters (arr[i]), one leaves (arr[i-k]) — updating by the difference costs O(1) per slide, O(n) total. The re-sum version computes the same numbers at O(k) per step: correct answers, O(n·k) bill; the whole point of the pattern is avoiding it. Adding without subtracting grows the window forever, and the last option forgets the window entirely.', hint: 'When the window moves one step right, exactly what changed? Two elements — which two?' },
            { type: 'realworld', prompt: 'Window of size k over n elements, updated by the slide trick — total cost?', scenario: '📊 Each slide adds one element and removes one.', options: [{ code: 'O(n)', label: 'Linear in n' }, { code: 'O(n * k)', label: 'n times k' }, { code: 'O(n²)', label: 'Quadratic' }, { code: 'O(k)', label: 'Just the window' }], correct: 0, explanation: 'The first window costs O(k), then each of the ~n slides costs O(1), so the total is O(n) — and k drops out of the asymptotics entirely, which is the point of the trick. O(n·k) is what re-summing every window costs; picking it usually means not trusting that the +/- update really replaces the loop.', hint: 'Count the cost of ONE slide with the trick. Then multiply by how many slides happen.' },
            { type: 'trace', prompt: 'Read and write pointers — what survives in arr[:w]?', code: [{ text: 'arr = [1,1,2,2,3]' }, { text: 'w = 1  # write pointer' }, { text: 'for r in range(1, len(arr)):' }, { text: '    if arr[r] != arr[r-1]:' }, { text: '        arr[w] = arr[r]; w += 1' }, { text: 'print(arr[:w])', highlight: true }], options: ['[1,2,3]', '[1,1,2]', '[2,3]', '[1,2,2,3]'], correct: 0, explanation: 'The read pointer visits everything; the write pointer only advances on a NEW value, so each distinct value is written once: [1,2,3]. The comparison arr[r] != arr[r-1] only works because the input is sorted — equal values are guaranteed adjacent. Same trick, zero extra memory: this is the two-pointer idea turned inward on one array.', hint: 'Walk r from 1 to 4. On which steps does the condition fire, and what gets written where?' },
            { type: 'output', prompt: 'What does this print for target 9?', code: [{ text: 'a = [1, 3, 5, 7, 11]  # sorted' }, { text: 'lo, hi = 0, len(a) - 1' }, { text: 'while lo < hi:' }, { text: '    s = a[lo] + a[hi]' }, { text: '    if s == 9: print(a[lo], a[hi]); break' }, { text: '    if s < 9: lo += 1' }, { text: '    else: hi -= 1' }], terminalOutput: '', options: ['Nothing — no pair sums to 9', '1 11', '3 7', '5 7'], correct: 0, explanation: 'Walk it: 1+11=12 too big, 1+7=8 too small, 3+7=10 too big, 3+5=8 too small, then lo meets hi and the loop ends. No pair sums to 9 — 3+7 is 10, not 9, which is the answer this question is really checking. The technique itself is O(n) on sorted input, against O(n²) for checking every pair.', hint: 'Do the arithmetic on each candidate pair rather than trusting the shape of the options.' },
            { type: 'bug', prompt: 'This two-pointer check gives the wrong answer. What is actually wrong?', code: [{ text: 'a = [5, 2, 9, 1]', hasError: true }, { text: 'lo, hi = 0, len(a) - 1', hasError: false }, { text: 'while lo < hi:', hasError: false }, { text: '    if a[lo] + a[hi] == target: return True', hasError: false }, { text: '    elif a[lo] + a[hi] < target: lo += 1', hasError: false }], correctLine: 0, explanation: 'The algorithm is fine; the INPUT breaks its precondition. Moving lo right only makes sense if that guarantees a LARGER value, which requires sorted data. On unsorted input the pointers move in the wrong direction and it returns a confident wrong answer — no error. Sort first, or use a set-based scan, which works unsorted in O(n).', hint: 'Why does moving lo to the right increase the sum? What does that assume about the list?' },
            { type: 'complexity', prompt: 'Finding a pair that sums to a target, in a SORTED list', optionA: { code: 'for i in range(len(a)):\n    for j in range(i+1, len(a)):\n        if a[i] + a[j] == t: return True', label: 'Every pair' }, optionB: { code: 'lo, hi = 0, len(a) - 1\nwhile lo < hi:\n    ...', label: 'Two pointers' }, correct: 'B', complexityA: 'O(n²)', complexityB: 'O(n)', explanation: 'Each step of the two-pointer version eliminates an entire row of candidates: if the sum is too big, EVERY pair using that hi is too big, so hi can move once and never come back. The pointers together cross the list once. That elimination is only valid because the list is sorted — which is the price of admission for the technique.', hint: 'When the sum is too large, how many candidate pairs does moving hi rule out at once?' },
            { type: 'fillgap', prompt: 'Complete: reverse a list in place with two pointers', codeParts: [{ text: 'lo, hi = 0, len(a) - 1\nwhile ', type: 'fixed' }, { text: 'lo < hi', type: 'gap', id: 'g1' }, { text: ':\n    a[lo], a[hi] = a[hi], a[lo]\n    lo += 1\n    hi -= 1', type: 'fixed' }], bank: ['lo < hi', 'lo <= hi', 'lo < len(a)', 'hi > 0'], correctFill: { g1: 'lo < hi' }, explanation: 'Stop as soon as the pointers meet — every element has already been placed by then. Using <= swaps the middle element of an odd-length list with itself, which is harmless but pointless. The other two run past the crossing point and swap everything BACK, so the list ends up exactly as it started: a bug that produces no error and no change.', hint: 'What happens after the pointers cross and keep going? Try it on [1,2,3,4].' },
            { type: 'realworld', prompt: 'Which one removes duplicates from a SORTED list in place?', scenario: '📋 [1,1,2,3,3] should become [1,2,3] using no extra list.', options: [{ code: 'w = 1\nfor r in range(1, len(a)):\n    if a[r] != a[w-1]:\n        a[w] = a[r]; w += 1\nreturn w', label: 'Read and write pointers' }, { code: 'return list(set(a))', label: 'Set round-trip' }, { code: 'for x in a:\n    if a.count(x) > 1: a.remove(x)', label: 'Count and remove' }, { code: 'return sorted(a)', label: 'Sort again' }], correct: 0, explanation: 'A slow write pointer and a fast read pointer is the classic in-place pattern: read scans, write only advances on a new value, and w ends up as the new length. The set version allocates a new list and, before Python 3.7 ordering guarantees, could scramble the order. Removing while iterating skips elements. And sorting an already sorted list changes nothing.', hint: 'The requirement says "no extra list". Which option allocates one?' },
        ],
        36: [
            { type: 'scramble', prompt: 'Assemble BFS', pieces: [{ id: 'a', text: 'from collections import deque' }, { id: 'b', text: 'def bfs(graph, start):' }, { id: 'c', text: '    q = deque([start])' }, { id: 'd', text: '    visited = {start}' }, { id: 'e', text: '    while q:' }, { id: 'f', text: '        node = q.popleft()' }, { id: 'g', text: '        for nb in graph[node]:' }, { id: 'h', text: '            if nb not in visited:' }, { id: 'i', text: '                visited.add(nb); q.append(nb)' }], distractors: [{ id: 'j', text: '        q.append(node)' }], correctOrder: ['a', 'b', 'c', 'd', 'e', 'f', 'g', 'h', 'i'], explanation: 'The start node must be in BOTH the queue and visited before the loop — seeding only the queue lets start be re-added through a cycle. popleft (not pop) is what makes it breadth-first at all. The spare line re-enqueues the node just removed: the queue never drains and the loop never ends.', hint: 'Two structures need seeding before the loop. And which end of the deque must removal come from?' },
            { type: 'trace', prompt: 'DFS from A — in what order do nodes print?', code: [{ text: '# A→[B,C], B→[D], C→[], D→[]' }, { text: 'def dfs(node, graph, seen=set()):' }, { text: '    if node in seen: return' }, { text: '    seen.add(node); print(node)' }, { text: '    for n in graph[node]: dfs(n, graph, seen)', highlight: true }], options: ['A B D C', 'A B C D', 'A C B D', 'D B C A'], correct: 0, explanation: 'Depth first: A, then A\'s first neighbour B, then B\'s neighbour D — only then does the recursion unwind back to A\'s second neighbour C. "A B C D" is BFS. One more thing worth noticing: seen=set() is a MUTABLE DEFAULT, the exact CH2 trap — call dfs twice and the second call inherits the first\'s visited set and prints nothing. Correct here, booby-trapped for reuse.', hint: 'Follow the first neighbour as deep as it goes before touching the second. And look hard at that default argument.' },
            { type: 'realworld', prompt: 'Roads have lengths. What does the shortest-route search need?', scenario: '🗺️ İzmir to Ankara: fewest KILOMETRES, not fewest roads.', options: [{ code: 'graph[a][b] = km; dijkstra(graph)', label: 'Weighted graph + Dijkstra' }, { code: 'cities = [...]; roads via indices', label: 'Array of cities' }, { code: 'bfs(graph)  # unweighted', label: 'Plain BFS' }, { code: 'tree with İzmir as root', label: 'A tree' }], correct: 0, explanation: 'BFS minimises the COUNT of edges; with distances on the edges, a two-hop motorway can beat a one-hop mountain pass, so the algorithm must weigh, and that is Dijkstra. The array stores cities but no connectivity. And a road network is not a tree — trees have exactly one route between any two nodes, which would make navigation software pointless.', hint: 'BFS counts hops. When is the fewest-hops route NOT the shortest in kilometres?' },
            { type: 'pair', prompt: 'Match each traversal to the question it answers', pairs: [{ id: 1, left: 'BFS', right: 'Fewest hops to the target' }, { id: 2, left: 'DFS', right: 'Is there any path at all' }, { id: 3, left: "Dijkstra", right: 'Cheapest route with weights' }, { id: 4, left: 'Topological sort', right: 'A valid order for dependencies' }], explanation: 'BFS expands ring by ring, so the first time it reaches a node it has used the fewest edges — only on an unweighted graph. Add weights and fewest edges stops meaning cheapest, which is where Dijkstra takes over.' },
            { type: 'bug', prompt: 'This DFS never returns on a graph with a cycle. Which line is missing a guard?', code: [{ text: 'def dfs(node):', hasError: false }, { text: '    print(node)', hasError: false }, { text: '    for n in graph[node]:', hasError: false }, { text: '        dfs(n)', hasError: true }], correctLine: 3, explanation: 'Nothing records where the walk has already been, so A → B → A recurses forever until Python raises RecursionError. The fix is a visited set checked before the recursive call. On a tree the same code is fine, which is why the bug only appears once a cycle exists.', hint: 'Follow the calls on a graph where A points to B and B points back to A.' },
            { type: 'complexity', prompt: 'BFS keeps taking from the front of its queue. Which holds up at scale?', scenario: '🕸️ A graph with 500,000 nodes.', options: [{ code: 'queue = [start]\nwhile queue:\n  node = queue.pop(0)', label: 'A plain list', complexity: 'O(n) per pop' }, { code: 'from collections import deque\nqueue = deque([start])\nwhile queue:\n  node = queue.popleft()', label: 'A deque', complexity: 'O(1) per pop' }], correct: 1, explanation: 'pop(0) shifts every remaining element one place left, so the queue alone costs O(n²) over a full traversal and swamps the graph work. deque is a doubly linked structure — taking from either end is constant. Same BFS, different asymptotics.' },
            { type: 'output', prompt: 'Does this graph have a cycle?', code: [{ text: 'g = {' }, { text: '    "A": ["B"],' }, { text: '    "B": ["C"],' }, { text: '    "C": ["A"],' }, { text: '}  # directed' }], terminalOutput: 'True', options: ['Yes — A to B to C and back to A', 'No — each node has one edge', 'No — it is a tree', 'Cannot tell without weights'], correct: 0, explanation: 'Following the arrows returns you to where you started, which is exactly what a cycle is. "One edge each" is true and irrelevant. It cannot be a tree — a tree with three nodes has two edges and no way back. And weights have nothing to do with connectivity: a cycle is about structure, not cost.', hint: 'Start at A and keep following arrows. Where do you end up?' },
            { type: 'trace', prompt: 'How many CONNECTED COMPONENTS does this graph have?', code: [{ text: 'g = {' }, { text: '    "A": ["B"], "B": ["A"],' }, { text: '    "C": ["D"], "D": ["C"],' }, { text: '    "E": [],' }, { text: '}', highlight: true }], options: ['3', '1', '2', '5'], correct: 0, explanation: 'A-B is one group, C-D is another, and the isolated E is a third — a lone vertex is still a component. Counting them is just BFS or DFS restarted from every unvisited node, which is why the standard loop is "for each vertex, if unseen, traverse and increment". Forgetting isolated vertices is the usual off-by-one here.', hint: 'Start a walk anywhere and see how far you get. Then start again from something you did not reach. Do not forget E.' },
            { type: 'complexity', prompt: 'Visiting every vertex of a graph', optionA: { code: '# adjacency matrix\nfor i in range(n):\n    for j in range(n):\n        if m[i][j]: ...', label: 'Matrix traversal' }, optionB: { code: '# adjacency list\nfor v in g:\n    for nb in g[v]: ...', label: 'List traversal' }, correct: 'B', complexityA: 'O(V²)', complexityB: 'O(V + E)', explanation: 'The matrix has to inspect every possible pair even when almost none are connected; the list only walks edges that exist. On a sparse graph — 10,000 vertices, 20,000 edges — that is 100 million checks against 30,000. The matrix only wins when the graph is dense enough that E approaches V².', hint: 'How many cells does the matrix version look at, regardless of how many edges exist?' },
            { type: 'fillgap', prompt: 'Complete: count connected components', codeParts: [{ text: 'seen = set()\ncount = 0\nfor v in g:\n    ', type: 'fixed' }, { text: 'if v not in seen:', type: 'gap', id: 'g1' }, { text: '\n        bfs(g, v, seen)\n        count += 1', type: 'fixed' }], bank: ['if v not in seen:', 'if v in seen:', 'if g[v]:', 'if len(seen) == 0:'], correctFill: { g1: 'if v not in seen:' }, explanation: 'Each traversal marks everything reachable, so a vertex still unseen when the loop reaches it must start a NEW component. Inverting the test counts only vertices already reached. Testing g[v] skips isolated vertices, which are components too. And the last option only ever fires on the first vertex, giving a count of 1 for every graph.', hint: 'The traversal marks a whole component. What does it mean if a vertex survived every traversal so far?' },
        ],
        // ═══ CH10: MASTERY ⭐⭐⭐⭐ ═══
        37: [
            { type: 'trace', prompt: 'This table starts at dp[0]=1 — what is dp[4]?', code: [{ text: '# dp[0]=1, dp[1]=1' }, { text: '# dp[2] = dp[1]+dp[0] = 2' }, { text: '# dp[3] = dp[2]+dp[1] = 3' }, { text: '# dp[4] = dp[3]+dp[2] = ?', highlight: true }], options: ['4', '5', '6', '8'], correct: 1, explanation: '3 + 2 = 5. Note this table is indexed differently from the CH8 version (dp[1]=1, dp[2]=2) yet lands on the same answers — dp[0]=1 encodes "one way to stand still", a base-case convention rather than a different algorithm. Recognising that two tables are the same recurrence shifted is a real skill.', hint: 'The last two rows are on screen. Add them.' },
            { type: 'realworld', prompt: 'Which of these actually needs DP?', scenario: '🧠 The test: overlapping subproblems + optimal substructure.', options: [{ code: '# LCS("ABCDE", "ACE") = "ACE"', label: 'Longest common subsequence' }, { code: '# largest value in one array', label: 'Find the max' }, { code: '# visit each element once', label: 'Print all elements' }, { code: '# a, b = b, a', label: 'Swap two variables' }], correct: 0, explanation: 'LCS branches on match-or-skip at every character pair, and those branches RE-REACH the same (i, j) states — overlapping subproblems, so a table pays for itself. Finding a max is one clean pass: subproblems, yes, but each solved exactly once, so DP adds nothing. The other two have no subproblems at all.', hint: 'Apply the test: does solving it re-ask the same smaller question twice?' },
            { type: 'pair', prompt: 'Match each DP classic to its recurrence idea', pairs: [{ id: 1, left: 'Fibonacci', right: 'dp[i] = dp[i-1] + dp[i-2]' }, { id: 2, left: 'Knapsack', right: 'Take the item, or skip it' }, { id: 3, left: 'LCS', right: 'Match chars, or skip one' }, { id: 4, left: 'Coin change', right: 'min(dp[amt−coin] + 1)' }], explanation: 'Four recurrences, two shapes: Fibonacci and coin change COMBINE counts or minima; knapsack and LCS DECIDE between including and excluding. Most DP problems you will ever meet are one of these two shapes wearing different clothes — identifying the shape is 80% of the solve.' },
            { type: 'fillgap', prompt: 'The item fits — what are the two choices to compare?', codeParts: [{ text: 'def knapsack(W, wt, val, n):\n    dp = [[0]*(W+1) for _ in range(n+1)]\n    for i in range(1, n+1):\n        for w in range(1, W+1):\n            if wt[i-1] <= w:\n                ', type: 'fixed' }, { text: 'dp[i][w] = max(val[i-1]+dp[i-1][w-wt[i-1]], dp[i-1][w])', type: 'gap', id: 'g1' }, { text: '\n            else:\n                dp[i][w] = dp[i-1][w]\n    return dp[n][W]', type: 'fixed' }], bank: ['dp[i][w] = max(val[i-1]+dp[i-1][w-wt[i-1]], dp[i-1][w])', 'dp[i][w] = val[i-1]', 'dp[i][w] = dp[i-1][w] + 1', 'dp[i][w] = w'], correctFill: { g1: 'dp[i][w] = max(val[i-1]+dp[i-1][w-wt[i-1]], dp[i-1][w])' }, explanation: 'Take it or leave it: taking earns val[i-1] but shrinks the remaining budget (note the dp[i-1] row — 0/1 means the item cannot be retaken), leaving keeps the previous best. max picks the winner. The distractors all forget one side of the choice, which is the entire content of the algorithm.', hint: 'Two futures: with the item (what does it cost?) and without. The cell holds the better one.' },
            { type: 'output', prompt: 'How many ways to climb 5 stairs taking 1 or 2 at a time?', code: [{ text: 'def ways(n):' }, { text: '    a, b = 1, 1' }, { text: '    for _ in range(n - 1):' }, { text: '        a, b = b, a + b' }, { text: '    return b' }, { text: '' }, { text: 'print(ways(5))' }], terminalOutput: '8', options: ['8', '5', '10', '16'], correct: 0, explanation: 'The answer for n is the answer for n-1 plus the answer for n-2 — to reach step n you arrived from one of exactly two places. That is the Fibonacci recurrence wearing a different hat: 1, 2, 3, 5, 8. Recognising a known recurrence inside a word problem is most of what DP interviews actually test.', hint: 'From which steps can you reach step 5? Add up the ways to reach each of those.' },
            { type: 'bug', prompt: 'This 0/1 knapsack lets you use an item twice. Which line causes it?', code: [{ text: 'dp = [0] * (cap + 1)', hasError: false }, { text: 'for w, v in items:', hasError: false }, { text: '    for c in range(w, cap + 1):', hasError: true }, { text: '        dp[c] = max(dp[c], dp[c - w] + v)', hasError: false }], correctLine: 2, explanation: 'Going UP means dp[c - w] may already include this same item from earlier in this pass — so it gets packed again. Iterating downward, range(cap, w - 1, -1), reads only values from the previous item. The direction of one loop is the entire difference between 0/1 and UNBOUNDED knapsack, and both are correct algorithms for different problems.', hint: 'When c is large, has dp[c - w] already been updated by this same item during this pass?' },
            { type: 'trace', prompt: 'What is the longest common subsequence of "ABCD" and "ACBD"?', code: [{ text: '#     ""  A  C  B  D' }, { text: '# ""   0  0  0  0  0' }, { text: '# A    0  1  1  1  1' }, { text: '# B    0  1  1  2  2' }, { text: '# C    0  1  2  2  2' }, { text: '# D    0  1  2  2  ?', highlight: true }], options: ['3', '2', '4', '1'], correct: 0, explanation: 'The last cell fills from the diagonal plus one, since D matches D: 2 + 1 = 3. "ABD" and "ACD" are both length-3 subsequences. Note the table is one row and column LARGER than the strings — that empty row and column are the base cases, and forgetting them is where most LCS off-by-ones come from.', hint: 'The characters at this cell match. Which neighbour does a match read from, and what does it add?' },
            { type: 'complexity', prompt: 'Coin change: fewest coins for an amount', optionA: { code: '# try every combination\ndef best(amount):\n    if amount == 0: return 0\n    return 1 + min(best(amount - c) for c in coins)', label: 'Plain recursion' }, optionB: { code: 'dp = [0] + [inf] * amount\nfor a in range(1, amount + 1):\n    dp[a] = 1 + min(dp[a - c] for c in coins if c <= a)', label: 'Bottom-up table' }, correct: 'B', complexityA: 'exponential', complexityB: 'O(amount × coins)', explanation: 'The recursion re-solves the same amounts down every branch — best(38) comes up on many different paths. The table computes each amount exactly once, so 100 amounts and 4 coin types is 400 operations rather than a tree that branches four ways at every level. Same recurrence, one of them memoised.', hint: 'How many times does the recursion compute the answer for amount 38?' },
            { type: 'realworld', prompt: 'Which one is NOT a dynamic programming problem?', scenario: '🧩 Three of these repeat subproblems. One does not.', options: [{ code: '# find the maximum of a list', label: 'Find the maximum' }, { code: '# longest common subsequence', label: 'LCS' }, { code: '# fewest coins for an amount', label: 'Coin change' }, { code: '# longest increasing subsequence', label: 'LIS' }], correct: 0, explanation: 'Finding a maximum is one linear pass with nothing to reuse — there is no smaller version of the question whose answer helps. The other three all ask the same subquestion repeatedly along different paths, which is exactly the condition a cache pays off under. Optimal substructure alone is not enough; the subproblems have to OVERLAP.', hint: 'Which of these has no smaller version of itself that gets asked more than once?' },
            { type: 'fillgap', prompt: 'Complete: maximum subarray sum (Kadane)', codeParts: [{ text: 'best = cur = a[0]\nfor x in a[1:]:\n    ', type: 'fixed' }, { text: 'cur = max(x, cur + x)', type: 'gap', id: 'g1' }, { text: '\n    best = max(best, cur)\nreturn best', type: 'fixed' }], bank: ['cur = max(x, cur + x)', 'cur = cur + x', 'cur = max(cur, x)', 'cur = min(x, cur + x)'], correctFill: { g1: 'cur = max(x, cur + x)' }, explanation: 'At each element the decision is exactly two-way: extend the run you are on, or abandon it and start fresh at x. Taking the larger is what discards a prefix that has gone negative. Plain cur + x can never restart and sinks with the negatives; max(cur, x) forgets the running sum entirely; and min inverts the whole problem.', hint: 'The running sum has gone negative. Is it still worth carrying into the next element?' },
        ],
        38: [
            { type: 'refactor', prompt: 'All primes up to a million — which approach scales?', originalCode: '# per-number testing:\nfor i in range(2, n+1):\n    if is_prime(i): result.append(i)', options: [{ code: 'sieve = [True]*(n+1)\nfor i in range(2, int(n**0.5)+1):\n    if sieve[i]:\n        for j in range(i*i, n+1, i):\n            sieve[j] = False', label: 'Sieve of Eratosthenes' }, { code: 'for i in range(2, n+1):\n    if all(i % d for d in range(2, i)):\n        result.append(i)', label: 'Trial-divide by everything' }, { code: 'import random\n# Miller-Rabin per number', label: 'Probabilistic tests' }], correct: 0, explanation: 'The sieve inverts the question: instead of asking "is each number prime?" it CROSSES OUT composites, each exactly once per prime factor — O(n log log n), nearly linear. Trial division re-derives the same factor information n times over. Miller-Rabin shines for testing a FEW huge numbers; for ALL numbers up to n it does per-number work the sieve shares.', hint: 'The brute force rediscovers that 6, 12, 18 are divisible by 3, one at a time. What would cross them out together?' },
            { type: 'pair', prompt: 'Match each pattern to the problem it unlocks', pairs: [{ id: 1, left: 'Sliding window', right: 'Best subarray of size k' }, { id: 2, left: 'Two pointer', right: 'Pair sum in sorted data' }, { id: 3, left: 'BFS', right: 'Fewest steps to reach' }, { id: 4, left: 'DP', right: 'Min coins for an amount' }], explanation: 'Pattern recognition is the interview meta-skill: "contiguous" points to a window, "sorted + pair" to two pointers, "fewest steps" to BFS, "min/max over choices with reuse" to DP. The keywords in a problem statement are the pattern announcing itself.' },
            { type: 'realworld', prompt: 'Hard interview problem, 40 minutes. What is the move?', scenario: '🎯 The interviewer wants to see your process, not just the answer.', options: [{ code: '# 1 brute force out loud\n# 2 name the bottleneck\n# 3 pick the structure that removes it\n# 4 code, then test edges', label: 'Brute force first, then optimise' }, { code: '# silently derive the optimal\n# solution before writing anything', label: 'Go straight for optimal' }, { code: '# write code immediately,\n# think while typing', label: 'Code first, think later' }, { code: '# recall a memorised solution\n# to a similar problem', label: 'Pattern-match from memory' }], correct: 0, explanation: 'The brute force is not a detour — it proves you understand the problem, banks a working answer, and its bottleneck POINTS at the optimisation. Hunting the optimal in silence stalls interviews; typing first produces code that solves the wrong problem; and memorised solutions crumble at the first follow-up question, which interviewers ask precisely to detect them.', hint: 'Which strategy still produces something valuable if you never find the clever trick?' },
            { type: 'scramble', prompt: 'Assemble the Sieve of Eratosthenes', pieces: [{ id: 'a', text: 'def sieve(n):' }, { id: 'b', text: '    is_prime = [True] * (n+1)' }, { id: 'c', text: '    is_prime[0] = is_prime[1] = False' }, { id: 'd', text: '    for i in range(2, int(n**0.5)+1):' }, { id: 'e', text: '        if is_prime[i]:' }, { id: 'f', text: '            for j in range(i*i, n+1, i):' }, { id: 'g', text: '                is_prime[j] = False' }, { id: 'h', text: '    return [i for i in range(n+1) if is_prime[i]]' }], distractors: [{ id: 'i', text: '            is_prime[i] = False' }], correctOrder: ['a', 'b', 'c', 'd', 'e', 'f', 'g', 'h'], explanation: 'Three refinements hide in the correct lines: crossing out starts at i*i (everything below already fell to a smaller prime), the outer loop stops at √n for the same reason, and the `if is_prime[i]` skips composites whose multiples are already gone. The spare line crosses out the prime ITSELF — run it and the sieve returns an empty list.', hint: 'Why start crossing out at i*i rather than 2*i? Who already handled 3i when i is 5?' },
            { type: 'output', prompt: 'What is the FIRST thing to establish about this problem?', code: [{ text: '# "Find two numbers in the list' }, { text: '#  that add up to the target."' }, { text: '' }, { text: '# What do you ask before writing code?' }], terminalOutput: '', options: ['Is the list sorted, and can values repeat?', 'Which language should I use?', 'How fast is the machine?', 'Should I use recursion?'], correct: 0, explanation: 'Sortedness decides the algorithm: sorted allows two pointers in O(n) with no extra memory, unsorted wants a hash set in O(n) with O(n) memory. Duplicates decide whether the same element can be used twice. Both change the answer, and neither is stated in the prompt — which is the point. The other three are decisions that come after, or not at all.', hint: 'Which of these, answered differently, would change the algorithm you write?' },
            { type: 'complexity', prompt: 'The interviewer says n can be 10^9. What does that rule out?', optionA: { code: 'for i in range(n):\n    ...', label: 'One pass over n' }, optionB: { code: '# arithmetic on n\nresult = n * (n + 1) // 2', label: 'Direct computation' }, correct: 'B', complexityA: 'O(n)', complexityB: 'O(1)', explanation: 'At 10^9 even a single linear pass is seconds to minutes, and allocating a list that size is gigabytes. Input SIZE is a constraint in disguise: 10^9 demands O(1) or O(log n); 10^6 allows O(n) or O(n log n); anything under about 25 permits exponential. Reading the bound tells you which family of solutions is on the table before you write anything.', hint: 'What does the size of the input tell you about which complexities are affordable?' },
            { type: 'realworld', prompt: 'Your solution passes the examples but times out. What next?', scenario: '⏱️ Correct on every test case, too slow on the large one.', options: [{ code: '# find the dominant term\n# and remove one factor of n', label: 'Analyse the complexity' }, { code: '# rewrite it in another language', label: 'Change language' }, { code: '# add more variables', label: 'Add variables' }, { code: '# submit it again', label: 'Retry' }], correct: 0, explanation: 'Timing out is a complexity problem, not a constant-factor one: an O(n²) solution on 10^6 items is not rescued by a faster language, which buys maybe 50x against the 10^6 you need. Find the nested loop or the repeated scan, then ask what removes it — usually a hash set for lookups, sorting to enable two pointers, or a cache for repeated subproblems.', hint: 'How much faster does a different language make you, and how much faster do you need to be?' },
            { type: 'pair', prompt: 'Match each clue in a problem statement to the technique it suggests', pairs: [{ id: 1, left: '"sorted array"', right: 'Binary search or two pointers' }, { id: 2, left: '"shortest path, unweighted"', right: 'BFS' }, { id: 3, left: '"count the ways"', right: 'Dynamic programming' }, { id: 4, left: '"k largest"', right: 'Heap of size k' }], explanation: 'Problem statements leak their solutions. "Sorted" is never mentioned by accident — it is there to be exploited. "Shortest" with no weights is BFS by definition. "Count the ways" almost always has overlapping subproblems. And "k largest" is the case where sorting everything is wasteful when a size-k heap answers it in O(n log k).', hint: null },
            { type: 'refactor', prompt: 'Which version is easiest to debug at 3am?', originalCode: 'return [x for s in data for x in s if x % 2 == 0 and x > threshold][:limit]', options: [{ code: 'flat = [x for s in data for x in s]\neven = [x for x in flat if x % 2 == 0]\nbig = [x for x in even if x > threshold]\nreturn big[:limit]', label: 'Named steps' }, { code: 'return list(filter(lambda x: x % 2 == 0 and x > threshold,\n                   [x for s in data for x in s]))[:limit]', label: 'filter with lambda' }, { code: 'return [x for s in data for x in s if x % 2 == 0 and x > threshold][:limit]', label: 'Keep the one-liner' }], correct: 0, explanation: 'Same output, but the named version can be inspected one step at a time — you can print flat and see immediately whether the flattening or the filtering is wrong. The one-liner gives you a single wrong answer with no way in. Clever code is not the code you want to be reading when something breaks; the cost is paid at debugging time, by whoever is on call.', hint: 'The output is wrong. Which version lets you find out WHERE without rewriting it first?' },
            { type: 'realworld', prompt: 'What should you do BEFORE optimising a slow function?', scenario: '🐌 Something in the request handler is slow.', options: [{ code: '# measure where the time goes\nimport cProfile\ncProfile.run("handler()")', label: 'Profile it' }, { code: '# rewrite the loop you suspect', label: 'Optimise the suspect' }, { code: '# add caching everywhere', label: 'Cache everything' }, { code: '# increase the server size', label: 'Bigger server' }], correct: 0, explanation: 'Intuition about where time goes is famously unreliable — the bottleneck is regularly in a line nobody suspected, often an accidental N+1 query or a repeated scan. Measure first, then optimise the thing that actually dominates. Caching everywhere adds invalidation bugs to a performance problem, and a bigger server buys a constant factor against what is usually a complexity issue.', hint: 'You have a suspicion about which line is slow. How confident should you be before rewriting it?' },
        ],
        39: [
            { type: 'fillgap', prompt: 'Reverse the list of characters in place', codeParts: [{ text: 'def reverse(chars):  # a LIST like ["a","b","c"]\n    lo, hi = 0, len(chars)-1\n    while lo < hi:\n        ', type: 'fixed' }, { text: 'chars[lo], chars[hi] = chars[hi], chars[lo]', type: 'gap', id: 'g1' }, { text: '\n        lo += 1; hi -= 1', type: 'fixed' }], bank: ['chars[lo], chars[hi] = chars[hi], chars[lo]', 'chars = chars[::-1]', 'lo, hi = hi, lo', 'chars[lo] = chars[hi]'], correctFill: { g1: 'chars[lo], chars[hi] = chars[hi], chars[lo]' }, explanation: 'The tuple swap exchanges the two ends without a temp. This works on a LIST — a Python string is immutable, so s[0] = "x" on a str raises TypeError, which is why in-place reversal is stated on a char list. The slice option builds a NEW reversed list and rebinds the local name — the caller\'s list is untouched. Swapping lo and hi swaps the POINTERS, and one-way copy loses a character.', hint: 'In place means the caller\'s list changes. Which options touch the actual elements?' },
            { type: 'terminal', prompt: 'FizzBuzz 1-15', expectedCommands: ['for i in range(1, 16):', '    if i%15==0: print("FizzBuzz")', '    elif i%3==0: print("Fizz")', '    elif i%5==0: print("Buzz")', '    else: print(i)'], hint: 'Check 15 first!', terminalHistory: [{ type: 'system', text: '>>> Interview: FizzBuzz' }] },
            { type: 'trace', prompt: 'Punctuation, spaces, case — does Panama pass?', code: [{ text: 'def is_palindrome(s):' }, { text: '    s = s.lower()' }, { text: '    s = "".join(c for c in s if c.isalnum())' }, { text: '    return s == s[::-1]' }, { text: 'print(is_palindrome("A man, a plan, a canal: Panama"))', highlight: true }], options: ['True', 'False', 'Error', 'None'], correct: 0, explanation: 'The two preprocessing lines are the actual answer: lowercase first, then strip everything non-alphanumeric — the residue is "amanaplanacanalpanama", a clean palindrome. Skip either step and the comparison fails on the capital A or the commas. Real string problems are usually 80% normalisation, 20% algorithm.', hint: 'Write out what s contains after line 3, then compare its ends.' },
            { type: 'scramble', prompt: 'Assemble the anagram check', pieces: [{ id: 'a', text: 'def is_anagram(s, t):' }, { id: 'b', text: '    if len(s) != len(t): return False' }, { id: 'c', text: '    from collections import Counter' }, { id: 'd', text: '    return Counter(s) == Counter(t)' }], distractors: [{ id: 'e', text: '    return s == t' }], correctOrder: ['a', 'b', 'c', 'd'], explanation: 'Counter equality compares letter multisets — same letters, same counts, order ignored. The length check first is a free O(1) rejection that skips building two Counters on obvious mismatches. Plain == demands identical ORDER too, so it rejects real anagrams like listen/silent.', hint: 'Why does the cheap length check come before the expensive Counter comparison?' },
            { type: 'realworld', prompt: 'One pattern family to drill first for interviews — which?', scenario: '💼 Ordered by how often they appear in real question banks.', options: [{ code: 'two_sum, group_anagrams, top_k...', label: 'Arrays + hashing' }, { code: 'clone_graph, course_schedule...', label: 'Graph algorithms' }, { code: 'edit_distance, coin_change...', label: 'Dynamic programming' }, { code: 'reverse_list, detect_cycle...', label: 'Linked lists' }], correct: 0, explanation: 'Array-and-hash questions are roughly 40% of what gets asked — two pointers, sliding windows, frequency maps — because they fit in 30 minutes and test day-job skills. Graphs (~15%), DP (~20%) and lists (~10%) matter, but they compound ON the array/hash foundations: LCS is a 2D array, BFS keeps a hash of seen nodes. Drill order should follow leverage.', hint: 'Which family do the OTHER families secretly depend on?' },
            { type: 'output', prompt: 'What does this print?', code: [{ text: 'def group(words):' }, { text: '    d = {}' }, { text: '    for w in words:' }, { text: '        k = "".join(sorted(w))' }, { text: '        d.setdefault(k, []).append(w)' }, { text: '    return list(d.values())' }, { text: '' }, { text: 'print(len(group(["eat","tea","tan","ate","nat"])))' }], terminalOutput: '2', options: ['2', '5', '3', '1'], correct: 0, explanation: 'Sorting the letters gives every anagram the same key, so eat/tea/ate land together and tan/nat land together — two groups. The whole trick is choosing a canonical form as the key; a letter-count tuple works too and is O(n) per word instead of O(n log n). setdefault creates the list on first sight, which is what defaultdict(list) does more readably.', hint: 'What key does each word get? How many DIFFERENT keys appear?' },
            { type: 'bug', prompt: 'This "find the missing number in 0..n" returns the wrong answer. Which line?', code: [{ text: 'def missing(a):', hasError: false }, { text: '    n = len(a)', hasError: false }, { text: '    return n * (n - 1) // 2 - sum(a)', hasError: true }, { text: '', hasError: false }, { text: '# missing([0,1,3]) should be 2', hasError: false }], correctLine: 2, explanation: 'With one number missing from 0..n the list holds n elements, so the full range runs to n and its total is n*(n+1)//2 — the formula here sums 0..n-1 and comes out one term short. The technique is right and O(1) in space; the arithmetic is off by exactly the value of n. Boundary arithmetic is where these clever one-liners go wrong.', hint: 'The list has 3 elements and the numbers run 0..3. Which sum does the formula on line 3 actually compute?' },
            { type: 'complexity', prompt: 'Two Sum on an UNSORTED list', optionA: { code: 'for i in range(len(a)):\n    for j in range(i+1, len(a)):\n        if a[i] + a[j] == t: return (i, j)', label: 'Every pair' }, optionB: { code: 'seen = {}\nfor i, x in enumerate(a):\n    if t - x in seen: return (seen[t-x], i)\n    seen[x] = i', label: 'Hash map of seen values' }, correct: 'B', complexityA: 'O(n²)', complexityB: 'O(n)', explanation: 'The hash version asks "have I already passed the number that completes this pair?" — one lookup per element, one pass. Note it does NOT need sorting, which is the point: sorting to enable two pointers costs O(n log n) and destroys the original indices, which this question asks for. Trading memory for time is the whole move.', hint: 'For each element there is exactly one partner that would work. How fast can you check whether you have already seen it?' },
            { type: 'realworld', prompt: 'The interviewer asks "can you do better than O(n²)?" What are they signalling?', scenario: '💬 Your solution is correct. They ask this anyway.', options: [{ code: '# a known technique removes\n# one factor of n', label: 'A better approach exists' }, { code: '# the solution is wrong', label: 'It is incorrect' }, { code: '# write it in another language', label: 'Wrong language' }, { code: '# add more comments', label: 'Needs comments' }], correct: 0, explanation: 'The question is an invitation, not a rejection — your answer works, and they want to see whether you can find the standard improvement. It is almost always one of three moves: a hash set to make lookups O(1), sorting to enable two pointers, or a cache for repeated subproblems. Say which one you are reaching for and why before you write it.', hint: 'They did not say it was wrong. What are the usual ways to remove one factor of n?' },
            { type: 'fillgap', prompt: 'Complete: is this string a palindrome, ignoring punctuation?', codeParts: [{ text: 'def is_pal(s):\n    ', type: 'fixed' }, { text: 'c = [ch.lower() for ch in s if ch.isalnum()]', type: 'gap', id: 'g1' }, { text: '\n    return c == c[::-1]', type: 'fixed' }], bank: ['c = [ch.lower() for ch in s if ch.isalnum()]', 'c = list(s)', 'c = s.split()', 'c = sorted(s)'], correctFill: { g1: 'c = [ch.lower() for ch in s if ch.isalnum()]' }, explanation: 'The requirement is doing the work here: drop anything that is not a letter or digit, and fold case, so "A man, a plan, a canal: Panama" reads the same both ways. Keeping every character fails on the commas; splitting gives words rather than characters; and sorting makes every string equal its own reverse, so the function would return True for everything.', hint: 'Which option makes the comparison blind to punctuation AND to case — and what does sorting do to the answer?' },
        ],
        40: [
            { type: 'trace', prompt: 'Start top-right — does this find 5?', code: [{ text: 'def search(m, t):' }, { text: '    r, c = 0, len(m[0])-1' }, { text: '    while r<len(m) and c>=0:' }, { text: '        if m[r][c]==t: return True' }, { text: '        elif m[r][c]>t: c-=1' }, { text: '        else: r+=1' }, { text: '    return False' }, { text: 'print(search([[1,4,7],[2,5,8],[3,6,9]], 5))', highlight: true }], options: ['True', 'False', 'Error', '[1,1]'], correct: 0, explanation: 'Walk it: 7>5 → left to 4; 4<5 → down to 5 → found, True. The top-right corner is the only place where the two sorted orders pull in opposite directions — bigger means step left, smaller means step down, and every comparison eliminates a full row or column. From the top-LEFT both moves increase the value and the logic collapses.', hint: 'Trace from 7: too big goes left, too small goes down. And note the function returns a boolean, not a position.' },
            { type: 'output', prompt: 'Each step kills a row or a column — total cost?', code: [{ text: '# start at the top-right corner' }, { text: '# every comparison discards one row OR one column' }, { text: '# rows m, columns n — how many discards fit?', highlight: true }], terminalOutput: 'O(m+n)', options: ['O(m×n)', 'O(m+n)', 'O(log(mn))', 'O(1)'], correct: 1, explanation: 'There are only m rows and n columns to discard, and each step discards exactly one — so at most m+n steps. m×n is checking every cell, exactly what the staircase avoids. O(log(mn)) would need to discard a fixed FRACTION per step, which this walk does not; a genuinely logarithmic variant exists but needs binary search inside the walk.', hint: 'Count the discardable things. That count IS the bound.' },
            { type: 'refactor', prompt: 'Max subarray sum in one pass — which idea?', originalCode: '# every (i, j) pair: O(n²)\nfor i in range(n):\n    curr = 0\n    for j in range(i, n):\n        curr += arr[j]\n        best = max(best, curr)', options: [{ code: 'curr = best = arr[0]\nfor x in arr[1:]:\n    curr = max(x, curr + x)\n    best = max(best, curr)', label: 'Extend or restart (Kadane)' }, { code: 'arr.sort()\nbest = sum(x for x in arr if x > 0)', label: 'Sort, sum the positives' }, { code: 'best = max(arr)', label: 'Take the single largest' }], correct: 0, explanation: 'Kadane\'s one decision per element — extend the running sum or restart here — works because a negative running sum can never help what follows. Sorting destroys adjacency, and SUBARRAY means contiguous, so the positives-sum answers a different question. The single largest element ignores that sums of several elements can beat any one.', hint: 'The word "subarray" means contiguous. Which options even preserve adjacency?' },
            { type: 'trace', prompt: 'Run Kadane on [-2,1,-3,4,-1,2,1,-5,4] — what is best?', code: [{ text: 'curr = best = -2' }, { text: '# each step: curr = max(x, curr+x)' }, { text: '#            best = max(best, curr)' }, { text: '# curr goes: -2, 1, -2, 4, 3, 5, 6, 1, 5' }, { text: '# best keeps the highest curr ever seen', highlight: true }], options: ['4', '6', '7', '5'], correct: 1, explanation: 'The curr row peaks at 6 — the subarray [4,-1,2,1] — and best holds that peak even as curr later sinks. The two-variable split is the algorithm: curr must be allowed to fall (or restart), best must never forget. Note the restart at index 3: curr was -2, so max(4, -2+4) chose to start fresh at 4.', hint: 'The curr sequence is given. best is simply its maximum — but find WHERE, and which subarray that was.' },
            { type: 'scramble', prompt: 'Assemble Kadane', pieces: [{ id: 'a', text: 'def max_subarray(nums):' }, { id: 'b', text: '    curr = best = nums[0]' }, { id: 'c', text: '    for x in nums[1:]:' }, { id: 'd', text: '        curr = max(x, curr + x)' }, { id: 'e', text: '        best = max(best, curr)' }, { id: 'f', text: '    return best' }], distractors: [{ id: 'g', text: '        curr += x' }], correctOrder: ['a', 'b', 'c', 'd', 'e', 'f'], explanation: 'Seeding with nums[0] (not 0) is what keeps all-negative inputs correct — [-3,-1] must answer -1, and a zero seed would claim 0 for an empty subarray that is not allowed. The spare line accumulates without the restart option: one bad prefix then poisons everything after it.', hint: 'Test the assembled code AND the spare line on [-3, -1]. Which gives -1?' },
            { type: 'output', prompt: 'What does this print?', code: [{ text: 'def f(a):' }, { text: '    best = cur = a[0]' }, { text: '    for x in a[1:]:' }, { text: '        cur = max(x, cur + x)' }, { text: '        best = max(best, cur)' }, { text: '    return best' }, { text: '' }, { text: 'print(f([-2, 1, -3, 4, -1, 2, 1, -5, 4]))' }], terminalOutput: '6', options: ['6', '4', '7', '5'], correct: 0, explanation: 'Kadane\'s algorithm, and the answer is the run [4, -1, 2, 1] = 6. The 7 is the tempting wrong answer — it is what you get by adding every positive number while ignoring that they are not contiguous. One pass, O(1) memory, and the decision at each step is only ever "extend or restart".', hint: 'The subarray has to be CONTIGUOUS. Which unbroken run adds up highest?' },
            { type: 'complexity', prompt: 'Merging k sorted lists of n items each', optionA: { code: '# concatenate, then sort\nsorted(chain(*lists))', label: 'Concatenate and sort' }, optionB: { code: '# heap of the k current heads\nheapq.merge(*lists)', label: 'k-way merge with a heap' }, correct: 'B', complexityA: 'O(kn log kn)', complexityB: 'O(kn log k)', explanation: 'The heap only ever holds k items — one head per list — so each of the kn elements costs log k rather than log kn. It also streams: you can consume the first result before reading all the input, which matters when the lists are files or network pages. Concatenating throws away the fact that each list is ALREADY sorted, which is the information worth exploiting.', hint: 'Each input list is already sorted. Which option uses that fact and which one discards it?' },
            { type: 'bug', prompt: 'This memoised solution returns wrong answers. Which line is the problem?', code: [{ text: 'def solve(i, remaining, memo={}):', hasError: false }, { text: '    if i == len(items): return 0', hasError: false }, { text: '    if i in memo: return memo[i]', hasError: true }, { text: '    r = best_choice(i, remaining)', hasError: false }, { text: '    memo[i] = r', hasError: false }, { text: '    return r', hasError: false }], correctLine: 2, explanation: 'The cache key must include EVERY input the answer depends on, and this one drops `remaining` — so the value computed for (i=3, remaining=10) is served for (i=3, remaining=2). Key on the tuple (i, remaining) instead. A key that is too narrow gives wrong answers rather than slow ones, which makes it far harder to spot than a cache that simply never hits.', hint: 'The result depends on two arguments. How many does the key use?' },
            { type: 'realworld', prompt: 'Which one finds the k most frequent words?', scenario: '📊 A million words, and you need the top 10.', options: [{ code: 'from collections import Counter\nCounter(words).most_common(k)', label: 'Counter, most_common' }, { code: 'sorted(set(words), key=words.count)[-k:]', label: 'Sort uniques by count' }, { code: 'sorted(words)[-k:]', label: 'Sort the words' }, { code: 'list(set(words))[:k]', label: 'First k uniques' }], correct: 0, explanation: 'Counter tallies in one pass and most_common uses a heap, so it is O(n log k). The second option calls words.count for every unique word, and each count rescans the million — the hidden quadratic. The third sorts alphabetically and returns the words nearest z, which has nothing to do with frequency, and the last returns arbitrary words in arbitrary order.', hint: 'One option looks concise and rescans the whole list once per unique word. Which?' },
            { type: 'fillgap', prompt: 'Complete: sieve of Eratosthenes', codeParts: [{ text: 'sieve = [True] * (n + 1)\nsieve[0] = sieve[1] = False\nfor i in range(2, int(n ** 0.5) + 1):\n    if sieve[i]:\n        for j in range(', type: 'fixed' }, { text: 'i * i', type: 'gap', id: 'g1' }, { text: ', n + 1, i):\n            sieve[j] = False', type: 'fixed' }], bank: ['i * i', 'i + 1', '2 * i', 'i'], correctFill: { g1: 'i * i' }, explanation: 'Every multiple of i below i² has a smaller prime factor and was already crossed out by that factor — so starting at i² skips redundant work. Starting at 2*i is correct but slower. Starting at i would cross out i ITSELF and report no primes at all, and i+1 crosses out numbers that are not multiples of i.', hint: 'When i is 5, has 10 already been crossed out by something? By what?' },
        ],
        41: [
            { type: 'pair', prompt: 'Match each concept to its meaning', pairs: [{ id: 1, left: 'Amortized O(1)', right: 'Cheap on average over many ops' }, { id: 2, left: 'NP-complete', right: 'No known fast exact solution' }, { id: 3, left: 'Space-time trade', right: 'Spend memory to save time' }, { id: 4, left: 'Greedy', right: 'Best local choice each step' }], explanation: 'Amortized is why list.append is called O(1) despite occasional O(n) resizes — the expensive ops are rare enough to average out. NP-complete does not mean unsolvable; it means every known exact algorithm goes exponential, so practice reaches for approximations. Memoisation is the space-time trade in its purest form.' },
            { type: 'trace', prompt: 'Sort by END time, take what fits — how many activities?', code: [{ text: 'acts = [(1,4),(3,5),(0,6),(5,7),(8,9),(5,9)]' }, { text: '# sort by end: (1,4),(3,5),(0,6),(5,7),(8,9),(5,9)' }, { text: '# take an activity if it starts at or after' }, { text: '# the last taken one ended', highlight: true }], options: ['3', '2', '4', '6'], correct: 0, explanation: 'Walk it: take (1,4); (3,5) and (0,6) start too early; take (5,7); (5,9) overlaps; take (8,9) — three. Sorting by end time is the load-bearing choice: finishing earliest leaves maximal room, and that greedy IS provably optimal here. Sort by start time or duration instead and counterexamples appear immediately.', hint: 'After taking (1,4), the next pick must start at 4 or later. Walk the sorted list.' },
            { type: 'realworld', prompt: 'On which of these does the greedy choice give a WRONG answer?', scenario: '⚠️ Greedy is provably optimal for some problems, merely tempting for others.', options: [{ code: 'coins = [1, 3, 4], amount = 6', label: 'Coin change' }, { code: 'pick the meeting that ends earliest, repeat', label: 'Activity selection' }, { code: 'coins = [1, 5, 10, 25], any amount', label: 'Change with standard coins' }, { code: 'merge the two rarest symbols, repeat', label: 'Huffman coding' }], correct: 0, explanation: 'On [1,3,4] making 6, greedy grabs 4 then 1+1 — three coins — while 3+3 needs two. Activity selection and Huffman have PROOFS of greedy optimality, and US-style coin systems are designed so greedy works. The lesson is that greedy needs a proof, not a vibe: the same strategy is optimal on one coin system and wrong on its neighbour.', hint: 'Three of these are textbook greedy-works proofs. Which is the textbook counterexample?' },
            { type: 'complexity', prompt: 'Same recursion, one line apart. Which one finishes?', scenario: '🧮 fib(40)', options: [{ code: 'def fib(n):\n  if n < 2: return n\n  return fib(n-1) + fib(n-2)', label: 'Plain recursion', complexity: 'O(2ⁿ)' }, { code: 'from functools import cache\n@cache\ndef fib(n):\n  if n < 2: return n\n  return fib(n-1) + fib(n-2)', label: 'Memoised', complexity: 'O(n)' }], correct: 1, explanation: 'The plain version recomputes the same subtrees over and over — about 1.6 billion calls at n=40. Caching each n turns the tree into a line of 40 calls. The recurrence is identical; only the repeated work is removed.' },
            { type: 'trace', prompt: 'Binary search on an empty range — where do lo and hi end up?', code: [{ text: 'lo, hi = 0, 4' }, { text: 'while lo < hi:' }, { text: '    mid = (lo + hi) // 2' }, { text: '    lo = mid + 1' }, { text: 'print(lo, hi)', highlight: true }], options: ['4 4', '3 4', '5 4', '2 4'], correct: 0, explanation: 'mid is 2 then 3, so lo climbs 3 then 4 and the loop stops the moment lo meets hi. lo < hi with lo = mid + 1 can never overshoot — that is the invariant that keeps a binary search from running off the end.', hint: 'Write the two passes out: mid, then the new lo, then re-test the condition.' },
            { type: 'algostep', prompt: 'Coin change for 6 with coins 1, 3, 4 — building the table left to right', array: ['dp[0]=0', 'dp[1]=1', 'dp[2]=2', 'dp[3]=1', 'dp[4]=1', 'dp[5]=2', 'dp[6]=?'], step: 6, description: 'Each cell is 1 + the best cell you can reach it from: dp[n] = min(dp[n-c]) + 1 over the coins c.', question: 'What is dp[6], the fewest coins for 6?', options: ['2', '3', '4', '6'], correct: 0, explanation: 'From 6 you can step back by 1, 3 or 4, reaching dp[5]=2, dp[3]=1 and dp[2]=2 — the best is dp[3], so dp[6] is 2 coins: 3+3. Greedy would grab the 4 first and finish with 4+1+1, three coins, which is exactly why coin change needs DP.', hint: 'Try each coin as the last one you place, and look up what the remainder already cost.' },
            { type: 'output', prompt: 'What does this print?', code: [{ text: 'from collections import Counter' }, { text: 'print(Counter("mississippi").most_common(2))' }], terminalOutput: "[('i', 4), ('s', 4)]", options: ["[('i', 4), ('s', 4)]", "[('s', 4), ('i', 4)]", "[('m', 1), ('p', 2)]", "[('i', 4), ('p', 2)]"], correct: 0, explanation: 'Both i and s appear four times, and most_common breaks the tie by FIRST-SEEN order — i appears before s in the string, so it comes first. Counter is built on a dict, which has preserved insertion order since Python 3.7, and that is what makes the tie-break predictable rather than arbitrary.', hint: 'Count each letter. Two of them tie — what decides which of those comes first?' },
            { type: 'bug', prompt: 'This returns True for any two words of the same length. Which line is wrong?', code: [{ text: 'def anagram(a, b):', hasError: false }, { text: '    return len(a) == len(b)', hasError: true }, { text: '', hasError: false }, { text: '# anagram("abc", "xyz") -> True ?!', hasError: false }], correctLine: 1, explanation: 'Equal length is a NECESSARY condition, not a sufficient one — it is the cheap pre-check, not the answer. sorted(a) == sorted(b) settles it, or Counter(a) == Counter(b) in O(n). Mistaking a fast filter for the real test is a whole family of bugs; the filter belongs first, with the real check behind it.', hint: '"abc" and "xyz" are both length 3. Are they anagrams?' },
            { type: 'fillgap', prompt: 'Complete: rotate a list right by k', codeParts: [{ text: 'def rotate(a, k):\n    k = k % len(a)\n    return ', type: 'fixed' }, { text: 'a[-k:] + a[:-k]', type: 'gap', id: 'g1' }, { text: '\n\n# rotate([1,2,3,4,5], 2) -> [4,5,1,2,3]', type: 'fixed' }], bank: ['a[-k:] + a[:-k]', 'a[k:] + a[:k]', 'a[:-k] + a[-k:]', 'a[::-1]'], correctFill: { g1: 'a[-k:] + a[:-k]' }, explanation: 'Rotating RIGHT moves the last k elements to the front, so the tail comes first. a[k:] + a[:k] rotates left, giving [3,4,5,1,2] — the same operation in the wrong direction. The third option reassembles the list unchanged, and reversing is a different transformation entirely. The k % len guard matters too: without it, k larger than the list raises or misbehaves.', hint: 'Right rotation by 2 should put 4 and 5 at the front. Which slice grabs the LAST two?' },
            { type: 'complexity', prompt: 'Checking whether any value appears twice', optionA: { code: 'for i in range(len(a)):\n    for j in range(i+1, len(a)):\n        if a[i] == a[j]: return True', label: 'Every pair' }, optionB: { code: 'return len(set(a)) != len(a)', label: 'Set size comparison' }, correct: 'B', complexityA: 'O(n²)', complexityB: 'O(n)', explanation: 'A set discards duplicates as it is built, so a shorter set means something was dropped — one pass, one comparison. The nested loops check up to half a million pairs on a thousand items. The trade is O(n) extra memory, which is almost always worth it; the one case it is not is when memory is the binding constraint and the input is already sorted, where a single adjacent-pair scan needs none.', hint: 'What happens to a duplicate when it is added to a set that already has it?' },
        ],
        42: [
            { type: 'realworld', prompt: 'The journey ends — what converts this knowledge into skill?', scenario: '🎓 Variables → flow → loops → functions → structures → algorithms → DP → graphs. Done.', options: [{ code: '# ship something real:\n# an app, an API, a contribution', label: 'Build projects' }, { code: '# restart the course from CH1', label: 'Repeat the course' }, { code: '# read more theory first', label: 'More reading' }, { code: '# wait until it feels solid', label: 'Wait for confidence' }], correct: 0, explanation: 'Courses teach recognition; projects force RECALL under ambiguity — no multiple choice, no highlighted line, requirements that change. That gap is where skill actually forms. Rereading and re-watching feel productive precisely because they stay in recognition mode. And confidence follows shipping; it does not precede it.', hint: 'Which option forces you to operate without the scaffolding this app has been providing?' },
            { type: 'pair', prompt: 'Map each stretch of the journey to what it taught', pairs: [{ id: 1, left: 'CH1–2', right: 'Variables and control flow' }, { id: 2, left: 'CH3–4', right: 'Loops and functions' }, { id: 3, left: 'CH5–7', right: 'Data structures' }, { id: 4, left: 'CH8–10', right: 'Algorithms and DP' }], explanation: 'The order was the argument: structures before algorithms because algorithms are choices ABOUT structures — you cannot weigh BFS against DFS before knowing what a queue and a stack cost. Anything foggy backward from here points at exactly which chapter to revisit.' },
            { type: 'trace', prompt: 'Final puzzle — what does mystery(5) return?', code: [{ text: 'def mystery(n):' }, { text: '    if n == 0: return 1' }, { text: '    return n * mystery(n-1)' }, { text: 'print(mystery(5))', highlight: true }], options: ['5', '15', '120', '720'], correct: 2, explanation: '5·4·3·2·1 = 120 — factorial, unnamed. Reading the recurrence (multiply by n, shrink by one, base 1) and recognising the function it defines is the exact skill this course has been building: 15 is the SUM 5+4+3+2+1, and 720 is 6!, one boundary off. If you got this, the journey worked.', hint: 'Base case 1, each level multiplies by n. Which well-known function is that?' },
            { type: 'output', prompt: 'What does this print?', code: [{ text: 'a = [3, 1, 2]' }, { text: 'b = sorted(a)' }, { text: 'c = a.sort()' }, { text: 'print(b, c)' }], terminalOutput: '[1, 2, 3] None', options: ['[1, 2, 3] None', '[1, 2, 3] [1, 2, 3]', 'None [1, 2, 3]', '[3, 1, 2] None'], correct: 0, explanation: 'sorted RETURNS a new list; list.sort sorts in place and returns None. Python is consistent about this — methods that mutate return None, which is why x = x.sort() and x = x.reverse() silently destroy your data. If a method changes the object, assume it hands back nothing.', hint: 'One of these builds a new list and one rearranges the existing one. What does the rearranging one return?' },
            { type: 'pair', prompt: 'Match each complexity to a familiar operation', pairs: [{ id: 1, left: 'O(1)', right: 'Dictionary lookup' }, { id: 2, left: 'O(log n)', right: 'Binary search' }, { id: 3, left: 'O(n log n)', right: 'Sorting' }, { id: 4, left: 'O(n²)', right: 'Comparing every pair' }], explanation: 'These four cover most of what you meet. The gaps between them are enormous at scale: on a million items that is roughly 1, 20, 20 million and a trillion operations. Knowing which class a piece of code falls into is usually more useful than knowing its exact constant.', hint: null },
            { type: 'trace', prompt: 'What is the value of result?', code: [{ text: 'data = [1, 2, 3, 4, 5, 6]' }, { text: 'result = sum(x * x for x in data if x % 2 == 0)' }, { text: 'print(result)', highlight: true }], options: ['56', '91', '20', '12'], correct: 0, explanation: 'Filter first, then square, then add: the evens are 2, 4, 6, whose squares are 4, 16, 36 — total 56. The 91 is every square added, ignoring the filter; the 12 is the evens added without squaring. The generator expression does all three in one pass without building an intermediate list, which is the difference from a list comprehension inside sum.', hint: 'Do the three steps in the order they are written: filter, square, add.' },
            { type: 'realworld', prompt: 'You have finished the journey. What is the fastest way to keep the skill?', scenario: '🎓 Ten chapters done. What now?', options: [{ code: '# read code you did not write,\n# and predict before you run', label: 'Read unfamiliar code' }, { code: '# reread these chapters', label: 'Reread the chapters' }, { code: '# memorise Big-O tables', label: 'Memorise complexities' }, { code: '# only write new code', label: 'Only write, never read' }], correct: 0, explanation: 'This whole app trains one thing: predicting what code does before running it. That skill transfers only if you keep aiming it at code you have not seen — an open-source pull request, a colleague\'s diff, your own code from six months ago. Rereading what you already know builds recognition rather than reading skill, tables without context fade, and writing alone never exposes you to unfamiliar styles.', hint: 'What was every exercise here actually asking you to do?' },
        ],
}
